// PRIVY COUNCIL (E)
// GET  /api/privy-council              — privy councillors + staff (admin/mod/speaker)
// POST /api/mod/privy-council/appoint  — admin/mod
// POST /api/mod/privy-council/remove   — admin/mod (restricted to non-permanent members)
// ═══════════════════════════════════════════════════════════════════════════

const privyReadLimit  = rateLimit({ windowMs: 60_000, max: 120, standardHeaders: true, legacyHeaders: false });
const privyWriteLimit = rateLimit({ windowMs: 60_000, max: 20,  standardHeaders: true, legacyHeaders: false });

app.get("/api/privy-council", privyReadLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;

    // Access gated: only privy councillors and staff (admin/mod/speaker)
    const isStaff = hasAdminModOrSpeaker(req);

    if (!isStaff) {
      // Check if current active character is a privy councillor
      if (!req.session.characterId) return res.status(403).json({ error: "Access restricted to Privy Councillors and staff" });
      const { rows: pcCheck } = await pool.query(
        "SELECT id FROM privy_council_members WHERE character_id = $1 AND removed_at IS NULL", [req.session.characterId]
      );
      if (!pcCheck.length) return res.status(403).json({ error: "Access restricted to Privy Councillors and staff" });
    }

    const { rows } = await pool.query(
      `SELECT pcm.id, pcm.character_id, pcm.appointed_at, pcm.sim_month, pcm.sim_year, pcm.reason,
              c.name AS character_name, c.party AS character_party, c.avatar AS character_avatar
         FROM privy_council_members pcm
         JOIN characters c ON c.id = pcm.character_id
        WHERE pcm.removed_at IS NULL
         ORDER BY pcm.appointed_at ASC`
    );
    const entries = rows.map((m) => ({ id: m.character_id, fallback: m.character_name || "" }));
    const displayNames = await batchGetCharacterDisplayNames(pool, entries);
    const members = rows.map((m, i) => ({ ...m, character_display_name: displayNames[i] }));
    res.json({ members });
  } catch (e) {
    console.error("[GET /api/privy-council]", e);
    res.status(500).json({ error: "Server error" });
  }
});

app.post("/api/mod/privy-council/appoint", privyWriteLimit, async (req, res) => {
  try {
    if (!requireAdminOrMod(req, res)) return;
    const { character_id, reason = "" } = req.body || {};
    if (!character_id) return res.status(400).json({ error: "character_id is required" });

    const { rows: charRows } = await pool.query(
      "SELECT id, name FROM characters WHERE id = $1 AND is_active = TRUE", [character_id]
    );
    if (!charRows.length) return res.status(404).json({ error: "Character not found or inactive" });

    const { simMonth, simYear } = await getCurrentSimMonthYear();
    const { rows: inserted } = await pool.query(
      `INSERT INTO privy_council_members (character_id, appointed_by, reason, sim_month, sim_year, removed_at, removed_by, removal_reason)
       VALUES ($1, $2, $3, $4, $5, NULL, NULL, '')
       ON CONFLICT (character_id)
       DO UPDATE SET removed_at = NULL, removed_by = NULL, removal_reason = '', appointed_at = NOW(),
                     sim_month = EXCLUDED.sim_month, sim_year = EXCLUDED.sim_year,
                     appointed_by = EXCLUDED.appointed_by, reason = EXCLUDED.reason
       RETURNING id`,
      [character_id, req.session.userId, String(reason).slice(0, 500), simMonth, simYear]
    );
    await writeAuditLog(req.session.userId, "privy_council.appoint", "character", character_id,
      {}, { reason });
    res.status(201).json({ ok: true });
  } catch (e) {
    console.error("[POST /api/mod/privy-council/appoint]", e);
    res.status(500).json({ error: "Server error" });
  }
});

app.post("/api/mod/privy-council/remove", privyWriteLimit, async (req, res) => {
  try {
    if (!requireAdminOrMod(req, res)) return;
    const { character_id, force = false } = req.body || {};
    if (!character_id) return res.status(400).json({ error: "character_id is required" });

    // Guard: block removal of characters who currently hold a permanent qualifying office
    // (PM, LoTO, Third Party Leader — these positions carry automatic lifetime PC membership).
    // Pass force: true in the request body to override (e.g. to correct a mistaken appointment).
    if (!force) {
      const thirdPartySlug = await getThirdPartySlug(pool);
      const { rows: permCheck } = await pool.query(
        `SELECT 1
           FROM office_assignments oa
           JOIN offices o ON o.id = oa.office_id
          WHERE oa.character_id = $1
            AND o.spec_id = ANY($2::text[])
         UNION ALL
         SELECT 1
           FROM parties
          WHERE leader_character_id = $1
            AND $3::text IS NOT NULL
            AND slug = $3
         LIMIT 1`,
        [character_id, RH_QUALIFYING_SPEC_IDS, thirdPartySlug]
      );
      if (permCheck.length) {
        return res.status(409).json({
          error: "Cannot remove a Privy Councillor who currently holds a permanent qualifying office (PM, LoTO, or Third Party Leader). Pass force: true to override for mistaken appointments."
        });
      }
    }

    const { rowCount } = await pool.query(
      `UPDATE privy_council_members
          SET removed_at = NOW(),
              removed_by = $2,
              removal_reason = COALESCE(NULLIF($3, ''), removal_reason)
        WHERE character_id = $1
          AND removed_at IS NULL`,
      [character_id, req.session.userId, String(req.body?.reason || '').slice(0, 500)]
    );
    if (!rowCount) return res.status(404).json({ error: "Character is not a Privy Councillor" });
    await writeAuditLog(req.session.userId, "privy_council.remove", "character", character_id, {}, { forced: !!force });
    res.json({ ok: true });
  } catch (e) {
    console.error("[POST /api/mod/privy-council/remove]", e);
    res.status(500).json({ error: "Server error" });
  }
});

// ── Privy Council Posts (like Red Lion but PC-access-gated) ──────────────────
// GET  /api/privy-council/posts       — privy councillors + staff
// POST /api/privy-council/posts       — privy councillors + staff
// DELETE /api/privy-council/posts/:id — admin/mod only

/** Check if the request has Privy Council access (current PC member or staff). */
async function hasPrivyCouncilAccess(req) {
  if (hasAdminModOrSpeaker(req)) return true;
  if (!req.session.characterId) return false;
  const { rows } = await pool.query(
    "SELECT id FROM privy_council_members WHERE character_id = $1 AND removed_at IS NULL",
    [req.session.characterId]
  );
  return rows.length > 0;
}

app.get("/api/privy-council/posts", privyReadLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    if (!(await hasPrivyCouncilAccess(req))) {
      return res.status(403).json({ error: "Access restricted to Privy Councillors and staff" });
    }
    const { rows } = await pool.query(
      `SELECT p.id, p.posted_as, p.posted_as_type, p.character_id, p.avatar_url,
              p.body, p.sim_month, p.sim_year, p.created_at,
              c.name AS character_name
         FROM privy_council_posts p
         LEFT JOIN characters c ON c.id = p.character_id
         ORDER BY p.created_at ASC`
    );
    res.json({ posts: rows });
  } catch (e) {
    console.error("[GET /api/privy-council/posts]", e);
    res.status(500).json({ error: "Server error" });
  }
});

app.post("/api/privy-council/posts", privyWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    if (!(await hasPrivyCouncilAccess(req))) {
      return res.status(403).json({ error: "Access restricted to Privy Councillors and staff" });
    }
    const { body, posted_as_type = "character" } = req.body || {};
    if (!body || !String(body).trim()) return res.status(400).json({ error: "Post body is required" });

    const isStaff = hasAdminModOrSpeaker(req);

    // Only staff may post as the Monarch
    if (posted_as_type === "monarch" && !isStaff) {
      return res.status(403).json({ error: "Only admin/mod/speaker may post as the Monarch" });
    }

    const { simMonth, simYear } = await getCurrentSimMonthYear();
    const sim = { month: simMonth, year: simYear };

    let postedAs = "The Monarch";
    let avatarUrl = "";
    let charId = null;

    if (posted_as_type === "character") {
      const aid = req.session.characterId;
      if (!aid) return res.status(400).json({ error: "No active character to post as" });
      const { rows: charRows } = await pool.query(
        "SELECT id, name, avatar FROM characters WHERE id = $1 AND is_active = TRUE", [aid]
      );
      if (!charRows.length) return res.status(400).json({ error: "Active character not found" });
      charId = charRows[0].id;
      postedAs = await getCharacterDisplayName(pool, charId, charRows[0].name || "");
      avatarUrl = charRows[0].avatar || "";
    }

    const { rows: inserted } = await pool.query(
      `INSERT INTO privy_council_posts (posted_as, posted_as_type, character_id, avatar_url, body, sim_month, sim_year)
       VALUES ($1, $2, $3, $4, $5, $6, $7) RETURNING id, created_at`,
      [postedAs, posted_as_type, charId, avatarUrl, String(body).trim().slice(0, 4000), sim.month, sim.year]
    );
    await writeAuditLog(req.session.userId, "privy_council.post", "privy_council_posts", inserted[0].id, null,
      { posted_as: postedAs, posted_as_type });
    res.status(201).json({ ok: true, post: inserted[0] });
  } catch (e) {
    console.error("[POST /api/privy-council/posts]", e);
    res.status(500).json({ error: "Server error" });
  }
});

app.delete("/api/privy-council/posts/:id", privyWriteLimit, async (req, res) => {
  try {
    if (!requireAdminOrMod(req, res)) return;
    const { rowCount } = await pool.query("DELETE FROM privy_council_posts WHERE id = $1", [req.params.id]);
    if (!rowCount) return res.status(404).json({ error: "Post not found" });
    await writeAuditLog(req.session.userId, "privy_council.post.delete", "privy_council_posts", req.params.id, null, {});
    res.json({ ok: true });
  } catch (e) {
    console.error("[DELETE /api/privy-council/posts/:id]", e);
    res.status(500).json({ error: "Server error" });
  }
});
const groupDraftReadLimit  = rateLimit({ windowMs: 60_000, max: 120, standardHeaders: true, legacyHeaders: false });
const groupDraftWriteLimit = rateLimit({ windowMs: 60_000, max: 30,  standardHeaders: true, legacyHeaders: false });

/**
 * Returns the character_id of the caller's active character, or null.
 * Also returns whether the caller is admin/mod/speaker.
 */
async function resolveCallerCharacter(req) {
  const isStaff = hasAdminModOrSpeaker(req);
  if (isStaff) return { isStaff: true, charId: null };
  if (!req.session.characterId) return { isStaff: false, charId: null };
  const { rows } = await pool.query(
    "SELECT id FROM characters WHERE id = $1 AND is_active = TRUE",
    [req.session.characterId]
  );
  return { isStaff: false, charId: rows[0]?.id || null };
}

/**
 * Check whether a character holds any office of the given type ('cabinet' or 'shadow').
 */
async function isOfficeHolder(charId, officeType) {
  const { rows } = await pool.query(
    `SELECT 1 FROM office_assignments oa
       JOIN offices o ON o.id = oa.office_id
      WHERE oa.character_id = $1 AND o.type = $2
      LIMIT 1`,
    [charId, officeType]
  );
  return rows.length > 0;
}

// GET /api/cabinet/drafts — fetch cabinet draft bills (cabinet members + admin/mod/speaker)
app.get("/api/cabinet/drafts", groupDraftReadLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const { isStaff, charId } = await resolveCallerCharacter(req);
    if (!isStaff) {
      if (!charId) return res.status(403).json({ error: "No active character" });
      const ok = await isOfficeHolder(charId, "cabinet");
      if (!ok) return res.status(403).json({ error: "Cabinet access only" });
    }
    const { rows } = await pool.query(
      "SELECT drafts FROM group_drafts WHERE group_key = 'cabinet'"
    );
    res.json({ drafts: rows[0]?.drafts || [] });
  } catch (e) {
    console.error("[GET /api/cabinet/drafts]", e);
    res.status(500).json({ error: "Server error" });
  }
});

// POST /api/cabinet/drafts — save cabinet draft bills (cabinet members + admin/mod/speaker)
// Body: { drafts: [...] }
app.post("/api/cabinet/drafts", groupDraftWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const { isStaff, charId } = await resolveCallerCharacter(req);
    if (!isStaff) {
      if (!charId) return res.status(403).json({ error: "No active character" });
      const ok = await isOfficeHolder(charId, "cabinet");
      if (!ok) return res.status(403).json({ error: "Cabinet access only" });
    }
    const { drafts } = req.body || {};
    if (!Array.isArray(drafts)) return res.status(400).json({ error: "Body must be { drafts: [] }" });
    await pool.query(
      `INSERT INTO group_drafts (group_key, drafts, updated_at)
          VALUES ('cabinet', $1::jsonb, NOW())
       ON CONFLICT (group_key)
       DO UPDATE SET drafts = EXCLUDED.drafts, updated_at = NOW()`,
      [JSON.stringify(drafts)]
    );
    res.json({ ok: true });
  } catch (e) {
    console.error("[POST /api/cabinet/drafts]", e);
    res.status(500).json({ error: "Server error" });
  }
});

