const SIM_MONTH_NAMES = ["January","February","March","April","May","June","July","August","September","October","November","December"];

// Canonical spec_id → full title map (mirrors government.js and opposition.js OFFICE_SPECS arrays)
const OFFICE_SPEC_TITLES = {
  "prime-minister":        "Prime Minister, First Lord of the Treasury, and Minister for the Civil Service",
  "chancellor":            "Chancellor of the Exchequer, and Second Lord of the Treasury",
  "home":                  "Secretary of State for the Home Department",
  "foreign":               "Secretary of State for Foreign and Commonwealth Affairs",
  "trade":                 "Secretary of State for Business and Trade, and President of the Board of Trade",
  "defence":               "Secretary of State for Defence",
  "welfare":               "Secretary of State for Work and Pensions",
  "education":             "Secretary of State for Education",
  "env-agri":              "Secretary of State for the Environment and Agriculture",
  "health":                "Secretary of State for Health and Social Care",
  "eti":                   "Secretary of State for Transport and Infrastructure",
  "culture":               "Secretary of State for Culture, Media and Sport",
  "home-nations":          "Secretary of State for the Home Nations",
  "leader-commons":        "Leader of the House of Commons",
  "leader-opposition":     "Leader of the Opposition",
  "shadow-chancellor":     "Shadow Chancellor of the Exchequer",
  "shadow-home":           "Shadow Secretary of State for the Home Department",
  "shadow-foreign":        "Shadow Secretary of State for Foreign and Commonwealth Affairs",
  "shadow-trade":          "Shadow Secretary of State for Business and Trade, and President of the Board of Trade",
  "shadow-defence":        "Shadow Secretary of State for Defence",
  "shadow-welfare":        "Shadow Secretary of State for Work and Pensions",
  "shadow-education":      "Shadow Secretary of State for Education",
  "shadow-env-agri":       "Shadow Secretary of State for the Environment and Agriculture",
  "shadow-health":         "Shadow Secretary of State for Health and Social Care",
  "shadow-eti":            "Shadow Secretary of State for Transport and Infrastructure",
  "shadow-culture":        "Shadow Secretary of State for Culture, Media and Sport",
  "shadow-home-nations":   "Shadow Secretary of State for the Home Nations",
  "shadow-leader-commons": "Shadow Leader of the House of Commons",
};

/** Returns { simMonth, simYear } for the current sim date (1-indexed month).
 *  Computes the real-time sim date from the live gameState (same algorithm as
 *  the navbar clock) so all server-side content stamps match what the UI shows.
 *  Falls back to the sim_clock DB cache if gameState is unavailable.
 */
async function getCurrentSimMonthYear() {
  try {
    const { rows } = await pool.query(
      `SELECT ss.data->'gameState' AS game_state
         FROM state_snapshots ss
         JOIN app_state_current asc2 ON ss.id = asc2.snapshot_id
        WHERE asc2.id = 'main'`
    );
    if (rows[0]?.game_state && typeof rows[0].game_state === "object") {
      const sd = computeSimDateFromGameState(rows[0].game_state);
      return { simMonth: sd.month, simYear: sd.year };
    }
  } catch (_) { /* fall through to sim_clock */ }
  const { rows: clk } = await pool.query("SELECT sim_current_month, sim_current_year FROM sim_clock WHERE id = 'main'");
  return clk[0]
    ? { simMonth: clk[0].sim_current_month, simYear: clk[0].sim_current_year }
    : { simMonth: 8, simYear: 1997 };
}

const officeReadLimit  = rateLimit({ windowMs: 60_000, max: 200, standardHeaders: true, legacyHeaders: false });
const officeWriteLimit = rateLimit({ windowMs: 60_000, max: 30,  standardHeaders: true, legacyHeaders: false });

app.get("/api/offices", officeReadLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const { rows } = await pool.query(`
      SELECT o.id, o.name, o.type, o.spec_id, o.created_at,
             json_agg(json_build_object(
               'character_id', a.character_id,
               'character_name', c.name,
               'assigned_at', a.assigned_at
             ) ORDER BY a.assigned_at) FILTER (WHERE a.character_id IS NOT NULL) AS assignments
        FROM offices o
        LEFT JOIN office_assignments a ON a.office_id = o.id
        LEFT JOIN characters c ON c.id = a.character_id
       GROUP BY o.id
       ORDER BY o.type, o.name
    `);
    res.json({ offices: rows.map((r) => ({ ...r, assignments: r.assignments || [] })) });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

app.post("/api/offices", officeWriteLimit, async (req, res) => {
  try {
    if (!requireAdmin(req, res)) return;
    const { name, type = "parliamentary" } = req.body || {};
    if (!name || typeof name !== "string" || !name.trim()) {
      return res.status(400).json({ error: "name is required" });
    }
    const validTypes = ["cabinet", "shadow", "parliamentary", "other"];
    if (!validTypes.includes(type)) {
      return res.status(400).json({ error: `type must be one of: ${validTypes.join(", ")}` });
    }
    const { rows } = await pool.query(
      "INSERT INTO offices (name, type) VALUES ($1, $2) RETURNING id, name, type, created_at",
      [name.trim(), type]
    );
    await writeAuditLog(req.session.userId, "office.create", "office", rows[0].id, null, rows[0]);
    res.status(201).json({ ok: true, office: rows[0] });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

app.post("/api/offices/:id/assign", officeWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const { character_id } = req.body || {};
    if (!character_id) return res.status(400).json({ error: "character_id is required" });

    // Verify office and character exist
    const [{ rows: offRows }, { rows: charRows }] = await Promise.all([
      pool.query("SELECT id, name, type, spec_id FROM offices WHERE id = $1", [req.params.id]),
      pool.query("SELECT id, name FROM characters WHERE id = $1", [character_id]),
    ]);
    if (!offRows.length)  return res.status(404).json({ error: "Office not found" });
    if (!charRows.length) return res.status(404).json({ error: "Character not found" });
    const office = offRows[0];

    // Permission: admin/mod always allowed; PM can assign non-PM cabinet; LOTO can assign non-LOTO shadow
    const isAdminOrMod = hasAdminOrMod(req);
    if (!isAdminOrMod) {
      const callerCharId = await getActiveCharacterId(req);
      if (!callerCharId) return res.status(403).json({ error: "Forbidden" });
      if (office.type === "cabinet" && office.spec_id !== "prime-minister") {
        const { rows: pmCheck } = await pool.query(
          `SELECT 1 FROM office_assignments oa JOIN offices o ON o.id = oa.office_id
            WHERE o.spec_id = 'prime-minister' AND oa.character_id = $1`, [callerCharId]
        );
        if (!pmCheck.length) return res.status(403).json({ error: "Only the Prime Minister or admin/mod can appoint cabinet offices" });
      } else if (office.type === "shadow" && office.spec_id !== "leader-opposition") {
        const { rows: lotoCheck } = await pool.query(
          `SELECT 1 FROM office_assignments oa JOIN offices o ON o.id = oa.office_id
            WHERE o.spec_id = 'leader-opposition' AND oa.character_id = $1`, [callerCharId]
        );
        if (!lotoCheck.length) return res.status(403).json({ error: "Only the Leader of the Opposition or admin/mod can appoint shadow offices" });
      } else {
        return res.status(403).json({ error: "Forbidden" });
      }
    }

    // Get current holder for salary recomputation
    const { rows: oldRows } = await pool.query(
      "SELECT character_id FROM office_assignments WHERE office_id = $1 LIMIT 1",
      [req.params.id]
    );
    const oldCharId = oldRows[0]?.character_id ?? null;

    // Fetch current sim date for history records
    const { simMonth, simYear } = await getCurrentSimMonthYear();

    // Close any open history records for previous holder of this office
    if (oldCharId && oldCharId !== character_id) {
      await pool.query(
        `UPDATE office_assignment_history
            SET end_sim_month = $1, end_sim_year = $2
          WHERE office_id = $3 AND character_id = $4 AND end_sim_month IS NULL`,
        [simMonth, simYear, req.params.id, oldCharId]
      );
    }

    // Exclusive assignment: clear any existing holders then insert new
    const { rows } = await pool.query(
      `INSERT INTO office_assignments (office_id, character_id)
       VALUES ($1, $2)
       ON CONFLICT (office_id, character_id) DO UPDATE SET assigned_at = NOW()
       RETURNING id, office_id, character_id, assigned_at`,
      [req.params.id, character_id]
    );
    await pool.query(
      "DELETE FROM office_assignments WHERE office_id = $1 AND character_id != $2",
      [req.params.id, character_id]
    );

    // Insert a new history record for this assignment (skip if already has an open record)
    await pool.query(
      `INSERT INTO office_assignment_history (office_id, character_id, start_sim_month, start_sim_year)
       SELECT $1, $2, $3, $4
        WHERE NOT EXISTS (
          SELECT 1 FROM office_assignment_history
           WHERE office_id = $1 AND character_id = $2 AND end_sim_month IS NULL
        )`,
      [req.params.id, character_id, simMonth, simYear]
    );

    // Permanently mark characters who hold PM or LoTO as "Right Honourable" for life.
    // rh_ever is set to TRUE the first time they are assigned to these offices and never reverted.
    if (RH_QUALIFYING_SPEC_IDS.includes(office.spec_id)) {
      await pool.query("UPDATE characters SET rh_ever = TRUE WHERE id = $1", [character_id]);
    }

    // tpl_ever is set to TRUE the first time they are assigned as third-party leader and never reverted.
    if (office.spec_id === "party-leader-3rd-4th") {
      await pool.query("UPDATE characters SET tpl_ever = TRUE WHERE id = $1", [character_id]);
    }

    // Auto-grant permanent Privy Council membership for PM / LoTO / Third-Party Leader.
    // PC status is never auto-removed when leaving these roles.
    // On re-appointment, only reactivate (clear removal fields) — preserve original appointed_at.
    if (PC_QUALIFYING_SPEC_IDS.includes(office.spec_id)) {
      await pool.query(
        `INSERT INTO privy_council_members (character_id, appointed_by, reason, sim_month, sim_year, removed_at, removed_by, removal_reason)
         VALUES ($1, $2, $3, $4, $5, NULL, NULL, '')
         ON CONFLICT (character_id)
         DO UPDATE SET removed_at = NULL, removed_by = NULL, removal_reason = '',
                       sim_month = COALESCE(privy_council_members.sim_month, EXCLUDED.sim_month),
                       sim_year  = COALESCE(privy_council_members.sim_year,  EXCLUDED.sim_year),
                       appointed_by = EXCLUDED.appointed_by, reason = EXCLUDED.reason`,
        [character_id, req.session.userId,
          `Auto-granted on appointment as ${OFFICE_SPEC_TITLES[office.spec_id] || office.name}`,
          simMonth, simYear]
      );
    }

    // Recompute salary positions for old and new holder
    const toRecompute = new Set([oldCharId, character_id].filter(Boolean));
    for (const charId of toRecompute) {
      await recomputeSalaryPositions(charId).catch((e) => console.error("[salary positions]", charId, e.message));
    }

    await writeAuditLog(req.session.userId, "office.assign", "office_assignment", rows[0].id,
      { old_character_id: oldCharId }, { office_id: req.params.id, character_id }, {
        headline: `${charRows[0].name} appointed as ${OFFICE_SPEC_TITLES[office.spec_id] || office.name}`,
        characterName: charRows[0].name,
        officeName: OFFICE_SPEC_TITLES[office.spec_id] || office.name,
        officeType: office.type,
        simMonth,
        simYear,
      });

    // Recompute office:* user roles for old and new holder; only sync when a Discourse-relevant role changed
    const officeRoleChanges = [character_id];
    if (oldCharId && oldCharId !== character_id) officeRoleChanges.push(oldCharId);
    let officeRolesChanged = false;
    for (const cid of officeRoleChanges) {
      const changed = await recomputeUserOfficeRoles(cid, req.session.userId).catch((e) => {
        console.warn("[office.assign] recomputeUserOfficeRoles failed for char=%s: %s", cid, e.message);
        return false;
      });
      if (changed) officeRolesChanged = true;
    }
    if (officeRolesChanged) {
      enqueueDiscourseGroupSync(`office assign: ${OFFICE_SPEC_TITLES[office.spec_id] || office.name}`);
    }

    // Recompute political capital for assigned (and displaced) character non-blockingly
    for (const cid of [character_id, oldCharId].filter(Boolean)) {
      fireRecompute("character-political-state", "office.assign", () => recomputeCharacterPoliticalState(cid), cid);
    }
    res.status(201).json({ ok: true, assignment: rows[0] });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

app.delete("/api/offices/:id/assign/:characterId", officeWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;

    // Permission check (same logic as assign)
    const [{ rows: offRows }, { rows: unCharRows }] = await Promise.all([
      pool.query("SELECT type, spec_id, name FROM offices WHERE id = $1", [req.params.id]),
      pool.query("SELECT name FROM characters WHERE id = $1", [req.params.characterId]),
    ]);
    if (!offRows.length) return res.status(404).json({ error: "Office not found" });
    const office = offRows[0];

    const isAdminOrMod = hasAdminOrMod(req);
    if (!isAdminOrMod) {
      const callerCharId = await getActiveCharacterId(req);
      if (!callerCharId) return res.status(403).json({ error: "Forbidden" });
      if (office.type === "cabinet" && office.spec_id !== "prime-minister") {
        const { rows: pmCheck } = await pool.query(
          `SELECT 1 FROM office_assignments oa JOIN offices o ON o.id = oa.office_id
            WHERE o.spec_id = 'prime-minister' AND oa.character_id = $1`, [callerCharId]
        );
        if (!pmCheck.length) return res.status(403).json({ error: "Forbidden" });
      } else if (office.type === "shadow" && office.spec_id !== "leader-opposition") {
        const { rows: lotoCheck } = await pool.query(
          `SELECT 1 FROM office_assignments oa JOIN offices o ON o.id = oa.office_id
            WHERE o.spec_id = 'leader-opposition' AND oa.character_id = $1`, [callerCharId]
        );
        if (!lotoCheck.length) return res.status(403).json({ error: "Forbidden" });
      } else {
        return res.status(403).json({ error: "Forbidden" });
      }
    }

    const { rowCount } = await pool.query(
      "DELETE FROM office_assignments WHERE office_id = $1 AND character_id = $2",
      [req.params.id, req.params.characterId]
    );
    if (!rowCount) return res.status(404).json({ error: "Assignment not found" });

    // Close the open history record for this character/office
    const { simMonth: unSimMonth, simYear: unSimYear } = await getCurrentSimMonthYear();
    await pool.query(
      `UPDATE office_assignment_history
          SET end_sim_month = $1, end_sim_year = $2
        WHERE office_id = $3 AND character_id = $4 AND end_sim_month IS NULL`,
      [unSimMonth, unSimYear, req.params.id, req.params.characterId]
    );

    // Recompute salary for removed character
    await recomputeSalaryPositions(req.params.characterId).catch((e) => console.error("[salary positions]", e.message));

    await writeAuditLog(req.session.userId, "office.unassign", "office_assignment",
      `${req.params.id}:${req.params.characterId}`, { office_id: req.params.id, character_id: req.params.characterId }, null, {
        headline: `${unCharRows[0]?.name || "Unknown Character"} removed from ${OFFICE_SPEC_TITLES[office.spec_id] || office.name}`,
        characterName: unCharRows[0]?.name || null,
        officeName: OFFICE_SPEC_TITLES[office.spec_id] || office.name,
        officeType: office.type,
        simMonth: unSimMonth,
        simYear: unSimYear,
      });

    // Recompute office:* user roles for the unassigned character; only sync when a Discourse-relevant role changed
    const unassignRolesChanged = await recomputeUserOfficeRoles(req.params.characterId, req.session.userId).catch((e) => {
      console.warn("[office.unassign] recomputeUserOfficeRoles failed: %s", e.message);
      return false;
    });
    if (unassignRolesChanged) {
      enqueueDiscourseGroupSync(`office unassign: ${OFFICE_SPEC_TITLES[office.spec_id] || office.name}`);
    }

    // Recompute political capital for unassigned character non-blockingly
    fireRecompute("character-political-state", "office.unassign", () => recomputeCharacterPoliticalState(req.params.characterId), req.params.characterId);
    res.json({ ok: true });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

// GET /api/characters/:id/offices-held — DB-backed office assignment history for Personal page
app.get("/api/characters/:id/offices-held", officeReadLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;

    const { rows: charRows } = await pool.query(
      "SELECT id FROM characters WHERE id = $1", [req.params.id]
    );
    if (!charRows.length) return res.status(404).json({ error: "Character not found" });

    // Fetch full history from office_assignment_history joined to offices for spec_id + type
    const { rows: histRows } = await pool.query(
      `SELECT oah.start_sim_month, oah.start_sim_year,
              oah.end_sim_month,   oah.end_sim_year,
              o.spec_id,           o.type AS office_type,
              o.name               AS office_name
         FROM office_assignment_history oah
         JOIN offices o ON o.id = oah.office_id
        WHERE oah.character_id = $1
        ORDER BY oah.start_sim_year, oah.start_sim_month`,
      [req.params.id]
    );

    const officesHeld = histRows.map((r) => {
      const specId = r.spec_id || "";
      const canonicalTitle = OFFICE_SPEC_TITLES[specId] || r.office_name;
      const startLabel = `${SIM_MONTH_NAMES[(r.start_sim_month || 1) - 1]} ${r.start_sim_year}`;
      const endLabel   = r.end_sim_month
        ? `${SIM_MONTH_NAMES[(r.end_sim_month || 1) - 1]} ${r.end_sim_year}`
        : null;
      // Derive office_type from spec_id if the stored type is missing or generic,
      // so shadow offices always surface as 'shadow' regardless of DB quirks.
      let officeType = r.office_type || "other";
      if (!officeType || officeType === "other" || officeType === "parliamentary") {
        if (specId === "leader-opposition" || specId.startsWith("shadow-")) officeType = "shadow";
        else if (OFFICE_SPEC_TITLES[specId] && !specId.startsWith("shadow-")) officeType = "cabinet";
      }
      return {
        spec_id:     specId,
        title:       canonicalTitle,
        office_type: officeType,
        start_sim:   startLabel,
        end_sim:     endLabel,
      };
    });

    res.json({ officesHeld });
  } catch (e) {
    console.error("[GET /api/characters/:id/offices-held]", e);
    res.status(500).json({ error: "Server error" });
  }
});

// ───────────────────────────────────────────────────────────────────────────
// Helper: create a breaking news story server-side (used by fire/resign/reset)
// ───────────────────────────────────────────────────────────────────────────
async function createBreakingNewsStory(actorId, headline, text) {
  try {
    const { simMonth, simYear } = await getCurrentSimMonthYear();
    const simDate = `${simMonth}/${simYear}`;
    const id = `breaking-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    await pool.query(
      `INSERT INTO news_stories (id, headline, text, category, image_url, is_breaking, flavour, sim_date, created_by)
       VALUES ($1,$2,$3,'Politics','',TRUE,FALSE,$4,$5)`,
      [id, headline, text, simDate, actorId || null]
    );
  } catch (err) {
    console.error("[createBreakingNewsStory]", err.message);
  }
}

// POST /api/offices/:id/fire — fire the current holder of the office (vacate first)
app.post("/api/offices/:id/fire", officeWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;

    const [{ rows: offRows }] = await Promise.all([
      pool.query("SELECT id, name, type, spec_id FROM offices WHERE id = $1", [req.params.id]),
    ]);
    if (!offRows.length) return res.status(404).json({ error: "Office not found" });
    const office = offRows[0];

    // Find current holder
    const { rows: assignRows } = await pool.query(
      `SELECT oa.character_id, c.name AS character_name
         FROM office_assignments oa JOIN characters c ON c.id = oa.character_id
        WHERE oa.office_id = $1 LIMIT 1`,
      [req.params.id]
    );
    if (!assignRows.length) return res.status(400).json({ error: "Office is already vacant" });
    const { character_id: firedCharId, character_name: firedCharName } = assignRows[0];

    // Permission: admin/mod, PM can fire cabinet (non-PM), LOTO can fire shadow (non-LOTO)
    const isAdminOrMod = hasAdminOrMod(req);
    if (!isAdminOrMod) {
      const callerCharId = await getActiveCharacterId(req);
      if (!callerCharId) return res.status(403).json({ error: "Forbidden" });
      if (office.type === "cabinet" && office.spec_id !== "prime-minister") {
        const { rows: pmCheck } = await pool.query(
          `SELECT 1 FROM office_assignments oa JOIN offices o ON o.id = oa.office_id
            WHERE o.spec_id = 'prime-minister' AND oa.character_id = $1`, [callerCharId]
        );
        if (!pmCheck.length) return res.status(403).json({ error: "Only the Prime Minister or admin/mod can fire ministers" });
      } else if (office.type === "shadow" && office.spec_id !== "leader-opposition") {
        const { rows: lotoCheck } = await pool.query(
          `SELECT 1 FROM office_assignments oa JOIN offices o ON o.id = oa.office_id
            WHERE o.spec_id = 'leader-opposition' AND oa.character_id = $1`, [callerCharId]
        );
        if (!lotoCheck.length) return res.status(403).json({ error: "Only the Leader of the Opposition or admin/mod can fire shadow ministers" });
      } else {
        return res.status(403).json({ error: "Forbidden" });
      }
    }

    // Determine PM/LOTO name for news template
    const officeTitle = OFFICE_SPEC_TITLES[office.spec_id] || office.name;
    let leaderName = "";
    if (office.type === "cabinet") {
      const { rows: pmRows } = await pool.query(
        `SELECT c.name FROM office_assignments oa JOIN offices o ON o.id = oa.office_id
           JOIN characters c ON c.id = oa.character_id
          WHERE o.spec_id = 'prime-minister' LIMIT 1`
      );
      leaderName = pmRows[0]?.name || "Prime Minister";
    } else {
      const { rows: lotoRows } = await pool.query(
        `SELECT c.name FROM office_assignments oa JOIN offices o ON o.id = oa.office_id
           JOIN characters c ON c.id = oa.character_id
          WHERE o.spec_id = 'leader-opposition' LIMIT 1`
      );
      leaderName = lotoRows[0]?.name || "Leader of the Opposition";
    }

    const { simMonth, simYear } = await getCurrentSimMonthYear();

    // Vacate the office
    await pool.query("DELETE FROM office_assignments WHERE office_id = $1 AND character_id = $2", [req.params.id, firedCharId]);
    await pool.query(
      `UPDATE office_assignment_history SET end_sim_month = $1, end_sim_year = $2
        WHERE office_id = $3 AND character_id = $4 AND end_sim_month IS NULL`,
      [simMonth, simYear, req.params.id, firedCharId]
    );
    await recomputeSalaryPositions(firedCharId).catch((e) => console.error("[salary positions]", e.message));

    // Breaking news
    const isShadow = office.type === "shadow";
    const newsHeadline = isShadow
      ? `Breaking: ${firedCharName} fired from the ${officeTitle}`
      : `Breaking: ${firedCharName} fired from the Government`;
    const newsText = isShadow
      ? `Breaking: The Leader of the Opposition, ${leaderName}, has fired the ${officeTitle}, ${firedCharName}. More as this story develops…`
      : `Breaking: Prime Minister ${leaderName} has fired the ${officeTitle}, ${firedCharName}. More as this story develops…`;
    await createBreakingNewsStory(req.session.userId, newsHeadline, newsText);

    await writeAuditLog(req.session.userId, "office.fire", "office_assignment",
      `${req.params.id}:${firedCharId}`,
      { office_id: req.params.id, character_id: firedCharId },
      null,
      {
        headline: `${firedCharName} fired from ${officeTitle}`,
        characterName: firedCharName,
        officeName: officeTitle,
        officeType: office.type,
        simMonth,
        simYear,
      }
    );

    // Recompute office:* user roles and sync Discourse groups for the fired character
    const fireRolesChanged = await recomputeUserOfficeRoles(firedCharId, req.session.userId).catch((e) => {
      console.warn("[office.fire] recomputeUserOfficeRoles failed for char=%s: %s", firedCharId, e.message);
      return false;
    });
    if (fireRolesChanged) {
      await writeAuditLog(req.session.userId, "discourse.sync.trigger", "office_assignment",
        `${req.params.id}:${firedCharId}`, null, null,
        { reason: `office fire: ${officeTitle}`, characterId: firedCharId }
      );
      enqueueDiscourseGroupSync(`office fire: ${officeTitle}`);
    }

    res.json({ ok: true });
  } catch (e) {
    console.error("[POST /api/offices/:id/fire]", e);
    res.status(500).json({ error: "Server error" });
  }
});

// POST /api/offices/:id/resign — current holder resigns (vacate first)
app.post("/api/offices/:id/resign", officeWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;

    const { rows: offRows } = await pool.query(
      "SELECT id, name, type, spec_id FROM offices WHERE id = $1", [req.params.id]
    );
    if (!offRows.length) return res.status(404).json({ error: "Office not found" });
    const office = offRows[0];

    // Find current holder
    const { rows: assignRows } = await pool.query(
      `SELECT oa.character_id, c.name AS character_name
         FROM office_assignments oa JOIN characters c ON c.id = oa.character_id
        WHERE oa.office_id = $1 LIMIT 1`,
      [req.params.id]
    );
    if (!assignRows.length) return res.status(400).json({ error: "Office is already vacant" });
    const { character_id: resignCharId, character_name: resignCharName } = assignRows[0];

    // Permission: current holder or admin/mod
    const isAdminOrMod = hasAdminOrMod(req);
    if (!isAdminOrMod) {
      const callerCharId = await getActiveCharacterId(req);
      if (!callerCharId || callerCharId !== resignCharId) {
        return res.status(403).json({ error: "Only the current office holder or admin/mod can resign from this office" });
      }
    }

    const officeTitle = OFFICE_SPEC_TITLES[office.spec_id] || office.name;
    const { simMonth, simYear } = await getCurrentSimMonthYear();

    // Vacate the office
    await pool.query("DELETE FROM office_assignments WHERE office_id = $1 AND character_id = $2", [req.params.id, resignCharId]);
    await pool.query(
      `UPDATE office_assignment_history SET end_sim_month = $1, end_sim_year = $2
        WHERE office_id = $3 AND character_id = $4 AND end_sim_month IS NULL`,
      [simMonth, simYear, req.params.id, resignCharId]
    );
    await recomputeSalaryPositions(resignCharId).catch((e) => console.error("[salary positions]", e.message));

    // Breaking news
    const isShadow = office.type === "shadow";
    const newsHeadline = isShadow
      ? `Breaking: ${resignCharName} resigns from ${officeTitle}`
      : `Breaking: ${resignCharName} resigns from the Government`;
    const newsText = isShadow
      ? `Breaking: The ${officeTitle}, ${resignCharName}, has resigned from the Official Opposition. More as this story develops…`
      : `Breaking: The ${officeTitle}, ${resignCharName}, has resigned from the Government. More as this story develops…`;
    await createBreakingNewsStory(req.session.userId, newsHeadline, newsText);

    await writeAuditLog(req.session.userId, "office.resign", "office_assignment",
      `${req.params.id}:${resignCharId}`,
      { office_id: req.params.id, character_id: resignCharId },
      null,
      {
        headline: `${resignCharName} resigned from ${officeTitle}`,
        characterName: resignCharName,
        officeName: officeTitle,
        officeType: office.type,
        simMonth,
        simYear,
      }
    );

    // Recompute office:* user roles and sync Discourse groups for the resigned character
    const resignRolesChanged = await recomputeUserOfficeRoles(resignCharId, req.session.userId).catch((e) => {
      console.warn("[office.resign] recomputeUserOfficeRoles failed for char=%s: %s", resignCharId, e.message);
      return false;
    });
    if (resignRolesChanged) {
      await writeAuditLog(req.session.userId, "discourse.sync.trigger", "office_assignment",
        `${req.params.id}:${resignCharId}`, null, null,
        { reason: `office resign: ${officeTitle}`, characterId: resignCharId }
      );
      enqueueDiscourseGroupSync(`office resign: ${officeTitle}`);
    }

    res.json({ ok: true });
  } catch (e) {
    console.error("[POST /api/offices/:id/resign]", e);
    res.status(500).json({ error: "Server error" });
  }
});

// POST /api/government/reset — admin/mod: vacate all cabinet offices, assign new PM
app.post("/api/government/reset", officeWriteLimit, async (req, res) => {
  try {
    if (!requireAdminOrMod(req, res)) return;
    const { newPmCharId } = req.body || {};
    if (!newPmCharId) return res.status(400).json({ error: "newPmCharId is required" });

    const { rows: charRows } = await pool.query("SELECT id, name FROM characters WHERE id = $1", [newPmCharId]);
    if (!charRows.length) return res.status(404).json({ error: "Character not found" });
    const newPmName = charRows[0].name;

    const { simMonth, simYear } = await getCurrentSimMonthYear();

    // Vacate all cabinet offices
    const { rows: cabinetRows } = await pool.query(
      `SELECT oa.office_id, oa.character_id FROM office_assignments oa
         JOIN offices o ON o.id = oa.office_id
        WHERE o.type = 'cabinet'`
    );
    if (cabinetRows.length) {
      const cabinetOfficeIds = cabinetRows.map((r) => r.office_id);
      await pool.query(
        "DELETE FROM office_assignments WHERE office_id = ANY($1::uuid[])",
        [cabinetOfficeIds]
      );
      await pool.query(
        `UPDATE office_assignment_history SET end_sim_month = $1, end_sim_year = $2
          WHERE end_sim_month IS NULL AND office_id = ANY($3::uuid[])`,
        [simMonth, simYear, cabinetOfficeIds]
      );
      const uniqueCabinetCharIds = [...new Set(cabinetRows.map((r) => r.character_id))];
      await Promise.all(
        uniqueCabinetCharIds.map((charId) =>
          recomputeSalaryPositions(charId).catch((e) => console.error("[salary positions]", charId, e.message))
        )
      );
    }

    // Assign new PM
    const { rows: pmOfficeRows } = await pool.query("SELECT id FROM offices WHERE spec_id = 'prime-minister' LIMIT 1");
    if (pmOfficeRows.length) {
      const pmOfficeId = pmOfficeRows[0].id;
      await pool.query(
        `INSERT INTO office_assignments (office_id, character_id) VALUES ($1, $2)
         ON CONFLICT (office_id, character_id) DO UPDATE SET assigned_at = NOW()`,
        [pmOfficeId, newPmCharId]
      );
      await pool.query(
        `INSERT INTO office_assignment_history (office_id, character_id, start_sim_month, start_sim_year)
         SELECT $1, $2, $3, $4 WHERE NOT EXISTS (
           SELECT 1 FROM office_assignment_history WHERE office_id = $1 AND character_id = $2 AND end_sim_month IS NULL
         )`,
        [pmOfficeId, newPmCharId, simMonth, simYear]
      );
      await pool.query("UPDATE characters SET rh_ever = TRUE WHERE id = $1", [newPmCharId]);
      await recomputeSalaryPositions(newPmCharId).catch((e) => console.error("[salary positions]", e.message));
    }

    // Breaking news
    const newsHeadline = `Breaking: New Government — ${newPmName} becomes Prime Minister`;
    const newsText = `Breaking: A new Government has been formed. ${newPmName} has become Prime Minister. More as this story develops…`;
    await createBreakingNewsStory(req.session.userId, newsHeadline, newsText);

    await writeAuditLog(req.session.userId, "government.reset", "government", "reset", null,
      { newPmCharId, newPmName, vacatedCount: cabinetRows.length },
      {
        headline: `Government reset — ${newPmName} appointed as Prime Minister`,
        simMonth,
        simYear,
      }
    );

    // Recompute office:* user roles for all affected characters and sync Discourse groups
    const cabinetCharIds = cabinetRows.map((r) => r.character_id);
    const govResetCharIds = [...new Set([...cabinetCharIds, newPmCharId])];
    for (const cid of govResetCharIds) {
      await recomputeUserOfficeRoles(cid, req.session.userId).catch((e) => {
        console.warn("[government.reset] recomputeUserOfficeRoles failed for char=%s: %s", cid, e.message);
      });
    }
    await writeAuditLog(req.session.userId, "discourse.sync.trigger", "government", "reset", null, null,
      { reason: "government reset", newPmCharId }
    );
    enqueueDiscourseGroupSync("government reset");

    res.json({ ok: true });
  } catch (e) {
    console.error("[POST /api/government/reset]", e);
    res.status(500).json({ error: "Server error" });
  }
});

