// POST /api/government/reshuffle — PM or admin/mod declares a government reshuffle
app.post("/api/government/reshuffle", officeWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;

    // Permission: admin/mod or current PM
    const isAdminOrMod = hasAdminOrMod(req);
    let callerCharId = null;
    if (!isAdminOrMod) {
      callerCharId = await getActiveCharacterId(req);
      if (!callerCharId) return res.status(403).json({ error: "Forbidden" });
      const { rows: pmCheck } = await pool.query(
        `SELECT c.name FROM office_assignments oa JOIN offices o ON o.id = oa.office_id
           JOIN characters c ON c.id = oa.character_id
          WHERE o.spec_id = 'prime-minister' AND oa.character_id = $1`, [callerCharId]
      );
      if (!pmCheck.length) return res.status(403).json({ error: "Only the Prime Minister or admin/mod can declare a reshuffle" });
    }

    const { simMonth: curMonth, simYear: curYear } = await getCurrentSimMonthYear();

    // Enforce 18 sim-month cooldown (admin/mod bypasses)
    if (!isAdminOrMod) {
      const { rows: lastRows } = await pool.query(
        `SELECT sim_month, sim_year FROM frontbench_reshuffles WHERE type = 'government'
          ORDER BY created_at DESC LIMIT 1`
      );
      if (lastRows.length) {
        const months = simMonthsBetween(lastRows[0].sim_year, lastRows[0].sim_month, curYear, curMonth);
        if (months < RESHUFFLE_COOLDOWN_SIM_MONTHS) {
          return res.status(400).json({
            error: `A reshuffle was declared ${months} sim month(s) ago. The cooldown is ${RESHUFFLE_COOLDOWN_SIM_MONTHS} sim months.`,
            monthsRemaining: RESHUFFLE_COOLDOWN_SIM_MONTHS - months,
          });
        }
      }
    }

    // Close any existing active reshuffle for government
    await pool.query(
      `UPDATE frontbench_reshuffles SET is_active = FALSE WHERE type = 'government' AND is_active = TRUE`
    );

    // Resolve PM name for news
    const { rows: pmRows } = await pool.query(
      `SELECT c.name FROM office_assignments oa JOIN offices o ON o.id = oa.office_id
         JOIN characters c ON c.id = oa.character_id
        WHERE o.spec_id = 'prime-minister' LIMIT 1`
    );
    const pmName = pmRows[0]?.name || "The Prime Minister";

    // Insert new reshuffle record
    const { rows: newRows } = await pool.query(
      `INSERT INTO frontbench_reshuffles (type, sim_month, sim_year, is_active, declared_by)
       VALUES ('government', $1, $2, TRUE, $3) RETURNING id`,
      [curMonth, curYear, callerCharId || null]
    );

    // Breaking news
    const newsHeadline = `Breaking: Prime Minister ${pmName} announces a Cabinet reshuffle`;
    const newsText = `Breaking: Prime Minister ${pmName} has decided to reshuffle their Frontbench. More as we have it…`;
    await createBreakingNewsStory(req.session.userId, newsHeadline, newsText);

    await writeAuditLog(req.session.userId, "government.reshuffle", "government", "reshuffle", null,
      { reshuffleId: newRows[0].id, pmName, simMonth: curMonth, simYear: curYear },
      { headline: `Government reshuffle declared by ${pmName}`, simMonth: curMonth, simYear: curYear }
    );

    res.json({ ok: true, reshuffleId: newRows[0].id });
  } catch (e) {
    console.error("[POST /api/government/reshuffle]", e);
    res.status(500).json({ error: "Server error" });
  }
});

// POST /api/government/reshuffle/end — PM or admin/mod ends the active reshuffle
app.post("/api/government/reshuffle/end", officeWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;

    const isAdminOrMod = hasAdminOrMod(req);
    if (!isAdminOrMod) {
      const callerCharId = await getActiveCharacterId(req);
      if (!callerCharId) return res.status(403).json({ error: "Forbidden" });
      const { rows: pmCheck } = await pool.query(
        `SELECT 1 FROM office_assignments oa JOIN offices o ON o.id = oa.office_id
          WHERE o.spec_id = 'prime-minister' AND oa.character_id = $1`, [callerCharId]
      );
      if (!pmCheck.length) return res.status(403).json({ error: "Only the Prime Minister or admin/mod can end a reshuffle" });
    }

    await pool.query(
      `UPDATE frontbench_reshuffles SET is_active = FALSE WHERE type = 'government' AND is_active = TRUE`
    );
    res.json({ ok: true });
  } catch (e) {
    console.error("[POST /api/government/reshuffle/end]", e);
    res.status(500).json({ error: "Server error" });
  }
});

// POST /api/opposition/reshuffle — LOTO or admin/mod declares an opposition reshuffle
app.post("/api/opposition/reshuffle", officeWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;

    const isAdminOrMod = hasAdminOrMod(req);
    let callerCharId = null;
    if (!isAdminOrMod) {
      callerCharId = await getActiveCharacterId(req);
      if (!callerCharId) return res.status(403).json({ error: "Forbidden" });
      const { rows: lotoCheck } = await pool.query(
        `SELECT c.name FROM office_assignments oa JOIN offices o ON o.id = oa.office_id
           JOIN characters c ON c.id = oa.character_id
          WHERE o.spec_id = 'leader-opposition' AND oa.character_id = $1`, [callerCharId]
      );
      if (!lotoCheck.length) return res.status(403).json({ error: "Only the Leader of the Opposition or admin/mod can declare a reshuffle" });
    }

    const { simMonth: curMonth, simYear: curYear } = await getCurrentSimMonthYear();

    if (!isAdminOrMod) {
      const { rows: lastRows } = await pool.query(
        `SELECT sim_month, sim_year FROM frontbench_reshuffles WHERE type = 'opposition'
          ORDER BY created_at DESC LIMIT 1`
      );
      if (lastRows.length) {
        const months = simMonthsBetween(lastRows[0].sim_year, lastRows[0].sim_month, curYear, curMonth);
        if (months < RESHUFFLE_COOLDOWN_SIM_MONTHS) {
          return res.status(400).json({
            error: `A reshuffle was declared ${months} sim month(s) ago. The cooldown is ${RESHUFFLE_COOLDOWN_SIM_MONTHS} sim months.`,
            monthsRemaining: RESHUFFLE_COOLDOWN_SIM_MONTHS - months,
          });
        }
      }
    }

    await pool.query(
      `UPDATE frontbench_reshuffles SET is_active = FALSE WHERE type = 'opposition' AND is_active = TRUE`
    );

    const { rows: lotoRows } = await pool.query(
      `SELECT c.name FROM office_assignments oa JOIN offices o ON o.id = oa.office_id
         JOIN characters c ON c.id = oa.character_id
        WHERE o.spec_id = 'leader-opposition' LIMIT 1`
    );
    const lotoName = lotoRows[0]?.name || "The Leader of the Opposition";

    const { rows: newRows } = await pool.query(
      `INSERT INTO frontbench_reshuffles (type, sim_month, sim_year, is_active, declared_by)
       VALUES ('opposition', $1, $2, TRUE, $3) RETURNING id`,
      [curMonth, curYear, callerCharId || null]
    );

    const newsHeadline = `Breaking: Leader of the Opposition ${lotoName} announces a Shadow Cabinet reshuffle`;
    const newsText = `Breaking: Leader of the Opposition ${lotoName} has decided to reshuffle their Frontbench. More as we have it…`;
    await createBreakingNewsStory(req.session.userId, newsHeadline, newsText);

    await writeAuditLog(req.session.userId, "opposition.reshuffle", "opposition", "reshuffle", null,
      { reshuffleId: newRows[0].id, lotoName, simMonth: curMonth, simYear: curYear },
      { headline: `Opposition reshuffle declared by ${lotoName}`, simMonth: curMonth, simYear: curYear }
    );

    res.json({ ok: true, reshuffleId: newRows[0].id });
  } catch (e) {
    console.error("[POST /api/opposition/reshuffle]", e);
    res.status(500).json({ error: "Server error" });
  }
});

// POST /api/opposition/reshuffle/end — LOTO or admin/mod ends the active opposition reshuffle
app.post("/api/opposition/reshuffle/end", officeWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;

    const isAdminOrMod = hasAdminOrMod(req);
    if (!isAdminOrMod) {
      const callerCharId = await getActiveCharacterId(req);
      if (!callerCharId) return res.status(403).json({ error: "Forbidden" });
      const { rows: lotoCheck } = await pool.query(
        `SELECT 1 FROM office_assignments oa JOIN offices o ON o.id = oa.office_id
          WHERE o.spec_id = 'leader-opposition' AND oa.character_id = $1`, [callerCharId]
      );
      if (!lotoCheck.length) return res.status(403).json({ error: "Only the Leader of the Opposition or admin/mod can end a reshuffle" });
    }

    await pool.query(
      `UPDATE frontbench_reshuffles SET is_active = FALSE WHERE type = 'opposition' AND is_active = TRUE`
    );
    res.json({ ok: true });
  } catch (e) {
    console.error("[POST /api/opposition/reshuffle/end]", e);
    res.status(500).json({ error: "Server error" });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// DIVISIONS (generic weighted voting engine)
// POST  /api/divisions/create    — admin: open a division
// POST  /api/divisions/:id/vote  — authenticated: cast vote
// POST  /api/divisions/:id/close — admin: close division and tally
// GET   /api/divisions           — authenticated: list divisions
// GET   /api/divisions/:id       — authenticated: get division with tally
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Compute a division tally identically for both live (GET) and concluded (POST /close)
 * endpoints so the ongoing visualisation and the final result are always in sync.
 *
 * Algorithm:
 *  1. Sum player effective_weights by vote direction.
 *  2. For each NPC party vote (excluding Sinn Féin / Speaker): add (seats − rebels)
 *     to the voted direction; add rebel seats to their chosen direction.
 *  3. For each playable-party rebel entry (Labour / Conservative / Lib Dem):
 *     deduct the rebel count proportionally from already-cast player weights, then
 *     add the rebel count to their chosen direction.
 *  4. Sinn Féin always abstains — add their seat count unconditionally to abstain.
 *
 * @param {object} db            - pg Pool or PoolClient (has .query())
 * @param {string} divisionId
 * @param {object} npcVotes      - { partyName: "aye"|"no"|"abstain" }
 * @param {object} rebelsByParty - { partyName: rebelCount }
 * @param {object} rebelsByPartyChoice - { partyName: "aye"|"no"|"abstain" }
 * @param {object} seatsByParty  - { partyName: seatCount } from constituencies DB
 * @returns {Promise<{aye:number, no:number, abstain:number}>}
 */
// computeDivisionTallyFromDb → server/division-helpers.js
const divReadLimit  = rateLimit({ windowMs: 60_000, max: 200, standardHeaders: true, legacyHeaders: false });
const divWriteLimit = rateLimit({ windowMs: 60_000, max: 60,  standardHeaders: true, legacyHeaders: false });

app.get("/api/divisions", divReadLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const { status } = req.query;
    let q;
    let params = [];

    if (status === "open") {
      // Use the same filtering logic as the admin dashboard so that stale/expired
      // divisions (whose sim-time or real-time deadline has passed, or whose parent
      // entity is no longer active) are not counted as open.
      const { rows: clockRows } = await pool.query(
        "SELECT sim_current_month, sim_current_year FROM sim_clock WHERE id = 'main'"
      );
      if (!clockRows.length) console.warn("[GET /api/divisions] sim_clock main row missing — using fallback 1/1900");
      const simMonth = Number(clockRows[0]?.sim_current_month || 1);
      const simYear  = Number(clockRows[0]?.sim_current_year  || 1900);
      const simDeadline = simDeadlineToText(simMonth, simYear);

      q = `SELECT id, entity_type, entity_id, title, status, closes_at, created_at
             FROM divisions d
            WHERE d.status = 'open'
              AND (d.closes_at_sim IS NULL OR d.closes_at_sim > $1)
              AND (d.closes_at IS NULL OR d.closes_at > NOW())
              AND (
                (d.entity_type = 'bill' AND EXISTS (
                  SELECT 1 FROM bills b WHERE b.id = d.entity_id
                    AND COALESCE(b.data->>'status', b.data->>'stage', 'open')
                          NOT IN ('closed','archived','passed','failed','royal_assent')
                ))
                OR (d.entity_type = 'motion' AND EXISTS (
                  SELECT 1 FROM motions m WHERE m.id = d.entity_id
                    AND COALESCE(m.data->>'status', 'open') NOT IN ('closed','archived')
                ))
                OR (d.entity_type = 'statement' AND EXISTS (
                  SELECT 1 FROM statements s WHERE s.id = d.entity_id
                    AND COALESCE(s.data->>'status', 'open') NOT IN ('closed','archived')
                ))
                OR (d.entity_type = 'regulation' AND EXISTS (
                  SELECT 1 FROM regulations r WHERE r.id = d.entity_id
                    AND COALESCE(r.data->>'status', 'open') NOT IN ('closed','archived')
                ))
                OR d.entity_type NOT IN ('bill','motion','statement','regulation')
              )
            ORDER BY created_at DESC`;
      params = [simDeadline];
    } else {
      q = "SELECT id, entity_type, entity_id, title, status, closes_at, created_at FROM divisions";
      if (status === "closed") {
        q += " WHERE status = $1"; params.push(status);
      }
      q += " ORDER BY created_at DESC";
    }

    const { rows } = await pool.query(q, params);
    res.json({ divisions: rows });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

app.get("/api/divisions/:id", divReadLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const { rows } = await pool.query(
      `SELECT id, entity_type, entity_id, title, status, closes_at, created_at,
              npc_votes, rebels_by_party, rebels_by_party_choice
         FROM divisions WHERE id = $1`,
      [req.params.id]
    );
    if (!rows.length) return res.status(404).json({ error: "Division not found" });

    const npcV    = rows[0].npc_votes            || {};
    const rebelP  = rows[0].rebels_by_party      || {};
    const rebelCh = rows[0].rebels_by_party_choice || {};
    const seatsByParty = await getPartySeatsFromConstituencies(pool);

    // Tally + per-party breakdown (includes NPC seats, rebels, Sinn Féin auto-abstain)
    const { tally, byParty } = await computeDivisionTallyFromDb(pool, req.params.id, npcV, rebelP, rebelCh, seatsByParty);

    const { rows: delegations } = await pool.query(
      `SELECT character_id, delegation_source_character_id
         FROM division_votes
        WHERE division_id = $1
          AND delegation_source_character_id IS NOT NULL`,
      [req.params.id]
    );

    const immutableResult = rows[0].immutable_result || null;

    res.json({ division: rows[0], tally, byParty, seatsByParty, delegationMap: delegations, immutableResult });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

// POST /api/divisions/create — admin/mod/speaker: create a division for a given entity
app.post("/api/divisions/create", divWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const canCreate = hasAdminModOrSpeaker(req);
    if (!canCreate) return res.status(403).json({ error: "admin, mod or speaker role required" });

    const { entity_type, entity_id, title = "", closes_at, closes_at_sim } = req.body || {};
    if (!entity_type || !entity_id) {
      return res.status(400).json({ error: "entity_type and entity_id are required" });
    }

    // Guard: prevent multiple open divisions for the same motion
    if (entity_type === "motion") {
      const { rows: existingRows } = await pool.query(
        `SELECT id FROM divisions WHERE entity_type = 'motion' AND entity_id = $1 AND status = 'open' LIMIT 1`,
        [String(entity_id)]
      );
      if (existingRows.length) {
        return res.status(409).json({
          error: "An open division already exists for this motion",
          divisionId: existingRows[0].id,
        });
      }
    }

    const { rows } = await pool.query(
      `INSERT INTO divisions (entity_type, entity_id, title, closes_at, closes_at_sim)
       VALUES ($1, $2, $3, $4, $5)
       RETURNING id, entity_type, entity_id, title, status, closes_at, closes_at_sim, npc_votes, rebels_by_party, rebels_by_party_choice, outcome, created_at`,
      [entity_type, String(entity_id), title, closes_at || null, closes_at_sim || null]
    );
    await writeAuditLog(req.session.userId, "division.create", "division", rows[0].id, null, rows[0]);
    res.status(201).json({ ok: true, division: rows[0] });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

// GET /api/divisions/for-entity/:entityType/:entityId — look up a division by entity
app.get("/api/divisions/for-entity/:entityType/:entityId", divReadLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const { entityType, entityId } = req.params;
    const { rows } = await pool.query(
      `SELECT id, entity_type, entity_id, title, status, closes_at, closes_at_sim,
              npc_votes, rebels_by_party, rebels_by_party_choice, outcome, created_at
         FROM divisions WHERE entity_type = $1 AND entity_id = $2
        ORDER BY created_at DESC LIMIT 1`,
      [entityType, entityId]
    );
    if (!rows.length) return res.status(404).json({ error: "No division found for this entity" });

    const division = rows[0];
    const npcV    = division.npc_votes            || {};
    const rebelP  = division.rebels_by_party      || {};
    const rebelCh = division.rebels_by_party_choice || {};
    const seatsByParty = await getPartySeatsFromConstituencies(pool);

    // Tally + per-party breakdown (includes NPC seats, rebels, Sinn Féin auto-abstain)
    const { tally, byParty } = await computeDivisionTallyFromDb(pool, division.id, npcV, rebelP, rebelCh, seatsByParty);

    // Caller's own vote and effective weight
    const charId = await getActiveCharacterId(req);
    let myVote = null;
    let myWeight = 0;
    if (charId) {
      const { rows: mv } = await pool.query(
        "SELECT vote, effective_weight AS weight FROM division_votes WHERE division_id = $1 AND character_id = $2",
        [division.id, charId]
      );
      myVote = mv[0] || null;

      // Compute the caller's current effective weight from constituencies DB, minus rebels for their party
      try {
        const { rows: charRows } = await pool.query(
          "SELECT name, party, whip_status FROM characters WHERE id = $1", [charId]
        );
        const charName = charRows[0]?.name || "";
        const charParty = charRows[0]?.party || "";
        const whipWithdrawn = charRows[0]?.whip_status === "withdrawn";
        if (whipWithdrawn) {
          myWeight = 1;
        } else {
          const seatsByPartyFresh = await getPartySeatsFromConstituencies(pool);
          const { rows: stateRows } = await pool.query(
            `SELECT ss.data FROM state_snapshots ss
               JOIN app_state_current asc2 ON ss.id = asc2.snapshot_id
              WHERE asc2.id = 'main'`
          );
          const statePlayers = Array.isArray(stateRows[0]?.data?.players) ? stateRows[0].data.players : [];
          const { effectiveWeights } = computeAllPlayerWeights(seatsByPartyFresh, statePlayers);
          const rawWeight = Number(effectiveWeights[charName] || 0);
          // Deduct rebel fraction from myWeight display
          const partyRebels = Number(division.rebels_by_party?.[charParty] ?? 0);
          if (partyRebels > 0 && rawWeight > 0) {
            const partyTotalWeight = Object.entries(effectiveWeights)
              .filter(([n]) => {
                const pl = statePlayers.find((p) => String(p.name || "") === n);
                return pl && String(pl.party || "") === charParty;
              })
              .reduce((s, [, w]) => s + Number(w), 0);
            const fraction = partyTotalWeight > 0 ? rawWeight / partyTotalWeight : 0;
            myWeight = Math.max(0, rawWeight - Math.round(fraction * partyRebels));
          } else {
            myWeight = rawWeight;
          }
        }
      } catch (wErr) { console.error("[division.for-entity myWeight]", wErr.message); /* weight display is best-effort */ }
    }

    res.json({ division, tally, byParty, seatsByParty, myVote, myWeight });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

// POST /api/divisions/:id/vote — cast or update the caller's vote
// Body: { vote: 'aye'|'no'|'abstain' }
// Weight is ALWAYS computed server-side from constituencies DB + player state (client-supplied weight is ignored).
app.post("/api/divisions/:id/vote", divWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const { vote } = req.body || {};
    if (!vote) return res.status(400).json({ error: "vote is required" });
    const validVotes = ["aye", "no", "abstain"];
    if (!validVotes.includes(vote)) {
      return res.status(400).json({ error: `vote must be one of: ${validVotes.join(", ")}` });
    }

    // Resolve the active character for the caller
    const charId = await getActiveCharacterId(req);
    if (!charId) return res.status(403).json({ error: "No active character. Select a character first." });

    // Verify division is open
    const { rows: divRows } = await pool.query(
      "SELECT id, status FROM divisions WHERE id = $1",
      [req.params.id]
    );
    if (!divRows.length) return res.status(404).json({ error: "Division not found" });
    if (divRows[0].status !== "open") return res.status(409).json({ error: "Division is closed" });

    // Get character name and party for weight computation and rebellion check
    const { rows: charRows } = await pool.query(
      "SELECT name, party, whip_status, is_npc FROM characters WHERE id = $1", [charId]
    );
    const charParty      = charRows[0]?.party       || null;
    const charName       = charRows[0]?.name        || null;
    const whipWithdrawn  = charRows[0]?.whip_status === "withdrawn";
    const isNpc          = Boolean(charRows[0]?.is_npc);

    // Compute effective weight server-side:
    //   seats from constituencies DB (authoritative source)
    //   player list from game state (for absence/delegation)
    //   MPs with whip withdrawn vote as Independents with weight=1
    //   NPC characters not present in state are injected synthetically to receive their party share.
    let effectiveWeight = 1;
    try {
      if (!whipWithdrawn) {
        const seatsByParty = await getPartySeatsFromConstituencies(pool);
        const { rows: stateRows } = await pool.query(
          `SELECT ss.data FROM state_snapshots ss
             JOIN app_state_current asc2 ON ss.id = asc2.snapshot_id
            WHERE asc2.id = 'main'`
        );
        const statePlayers = Array.isArray(stateRows[0]?.data?.players) ? stateRows[0].data.players : [];
        effectiveWeight = computeCharacterWeight(seatsByParty, statePlayers, charName, charParty, isNpc);
      }
      // whipWithdrawn: effectiveWeight stays 1
    } catch (wErr) {
      console.error("[division.vote weight-calc]", wErr.message);
      // Fall back to weight=1 so the vote is still recorded
    }

    // Save vote (upsert) — client-supplied weight is always ignored
    const { rows: voteRows } = await pool.query(
      `INSERT INTO division_votes (division_id, character_id, vote, weight, effective_weight, delegation_source_character_id)
       VALUES ($1, $2, $3, $4, $4, NULL)
       ON CONFLICT (division_id, character_id)
       DO UPDATE SET vote = EXCLUDED.vote, weight = EXCLUDED.weight, effective_weight = EXCLUDED.effective_weight,
                     delegation_source_character_id = NULL, voted_at = NOW()
       RETURNING id, division_id, character_id, vote, weight, effective_weight, delegation_source_character_id, voted_at`,
      [req.params.id, charId, vote, effectiveWeight]
    );

    // Rebellion logging: keep a single authoritative rebellion record per (division, character)
    // so party-pressure calculations reflect current vote intent, not historical toggles.
    if (charParty) {
      try {
        const { rows: instrRows } = await pool.query(
          `SELECT position, whip_level, set_at_sim FROM division_party_instructions
            WHERE division_id = $1 AND party_slug = $2`,
          [req.params.id, charParty]
        );

        // Remove any stale rebellion log first (e.g. player changed vote back to party line).
        await pool.query(
          `DELETE FROM division_rebellion_log
            WHERE division_id = $1 AND character_id = $2`,
          [req.params.id, charId]
        );

        if (instrRows.length) {
          const instr = instrRows[0];
          if (instr.position !== "free" && instr.position !== vote) {
            // Get current sim date for recording
            const { rows: clk } = await pool.query(
              "SELECT sim_current_month, sim_current_year FROM sim_clock WHERE id = 'main'"
            );
            const sm = clk[0]?.sim_current_month ?? 8;
            const sy = clk[0]?.sim_current_year  ?? 1997;
            const simStr = `${sy}-${String(sm).padStart(2, "0")}`;
            await pool.query(
              `INSERT INTO division_rebellion_log
                 (division_id, character_id, party_slug, party_position, mp_vote, whip_level, recorded_at_sim)
               VALUES ($1, $2, $3, $4, $5, $6, $7)`,
              [req.params.id, charId, charParty, instr.position, vote, instr.whip_level, simStr]
            );
          }
        }
      } catch (rebErr) {
        console.error("[division.vote rebellion-log]", rebErr.message);
      }
    }

    // Return updated tally
    const { rows: tallyRows } = await pool.query(
      `SELECT vote, SUM(effective_weight) AS total_weight FROM division_votes WHERE division_id = $1 GROUP BY vote`,
      [req.params.id]
    );
    const tally = { aye: 0, no: 0, abstain: 0 };
    tallyRows.forEach((v) => { tally[v.vote] = Number(v.total_weight); });

    res.json({ ok: true, vote: voteRows[0], tally });

    // Non-blocking: recompute political state after vote (rebellion may have been logged)
    if (charId) {
      fireRecompute("character-political-state", "division.vote", () => recomputeCharacterPoliticalState(charId), charId);
    }
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

// POST /api/divisions/:id/close — admin/mod/speaker: close a division and compute outcome
app.post("/api/divisions/:id/close", divWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const canClose = hasAdminModOrSpeaker(req);
    if (!canClose) return res.status(403).json({ error: "admin, mod or speaker role required" });

    // Fetch constituency seat totals (authoritative source) outside the transaction
    const seatsByParty = await getPartySeatsFromConstituencies(pool);

    const client = await pool.connect();
    try {
      await client.query("BEGIN");
      const { rows: divRows } = await client.query(
        "SELECT id, status, entity_type, entity_id, title, npc_votes, rebels_by_party, rebels_by_party_choice FROM divisions WHERE id = $1 FOR UPDATE",
        [req.params.id]
      );
      if (!divRows.length) { await client.query("ROLLBACK"); return res.status(404).json({ error: "Division not found" }); }
      if (divRows[0].status === "closed") { await client.query("ROLLBACK"); return res.status(409).json({ error: "Already closed" }); }

      const npcVotes    = divRows[0].npc_votes            || {};
      const rebelsByPty = divRows[0].rebels_by_party      || {};
      const rebelChoicePty = divRows[0].rebels_by_party_choice || {};

      // Shared tally logic (identical to GET endpoints)
      const { tally } = await computeDivisionTallyFromDb(client, req.params.id, npcVotes, rebelsByPty, rebelChoicePty, seatsByParty);

      const outcome = tally.aye > tally.no ? "passed" : tally.no > tally.aye ? "failed" : "tied";
      const immutableResult = { tally, outcome, closedAt: new Date().toISOString() };
      await client.query(
        "UPDATE divisions SET status = 'closed', outcome = $2, immutable_result = $3::jsonb WHERE id = $1",
        [req.params.id, outcome, JSON.stringify(immutableResult)]
      );

      await client.query("COMMIT");
      await writeAuditLog(req.session.userId, "division.close", "division", req.params.id, divRows[0], { ...divRows[0], status: "closed", tally, outcome });
      res.json({ ok: true, division: { ...divRows[0], status: "closed", outcome, immutable_result: immutableResult }, tally, immutableResult });
    } catch (err) {
      await client.query("ROLLBACK");
      throw err;
    } finally {
      client.release();
    }
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

// PATCH /api/divisions/:id/npc-votes — admin/mod/speaker: set NPC vote positions and rebel counts
app.patch("/api/divisions/:id/npc-votes", divWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const canSet = hasAdminModOrSpeaker(req);
    if (!canSet) return res.status(403).json({ error: "admin, mod or speaker role required" });

    const { npc_votes = {}, rebels_by_party = {}, rebels_by_party_choice = {} } = req.body || {};
    const { rows } = await pool.query(
      `UPDATE divisions SET npc_votes = $1::jsonb, rebels_by_party = $2::jsonb, rebels_by_party_choice = $4::jsonb
        WHERE id = $3
       RETURNING id, npc_votes, rebels_by_party, rebels_by_party_choice`,
      [JSON.stringify(npc_votes), JSON.stringify(rebels_by_party), req.params.id, JSON.stringify(rebels_by_party_choice)]
    );
    if (!rows.length) return res.status(404).json({ error: "Division not found" });
    res.json({ ok: true, division: rows[0] });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

// ── Division party instruction endpoints ────────────────────────────────────
// POST /api/divisions/:divisionId/party-instruction
// Body: { partySlug, position, whipLevel, note? }
// Requires: admin/mod, OR the party's Chief Whip (Party Leader as fallback if no whip assigned)
app.post("/api/divisions/:divisionId/party-instruction", divWriteLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const { partySlug, position, whipLevel = 0, note = "" } = req.body || {};
    if (!partySlug || !position) return res.status(400).json({ error: "partySlug and position are required" });
    const validPos = ["aye", "no", "abstain", "free"];
    if (!validPos.includes(position)) return res.status(400).json({ error: `position must be one of: ${validPos.join(", ")}` });
    if (![0,1,2,3].includes(Number(whipLevel))) return res.status(400).json({ error: "whipLevel must be 0, 1, 2 or 3" });

    // Verify division exists
    const { rows: divRows } = await pool.query("SELECT id, status FROM divisions WHERE id = $1", [req.params.divisionId]);
    if (!divRows.length) return res.status(404).json({ error: "Division not found" });
    if (divRows[0].status !== "open") return res.status(409).json({ error: "Division is closed" });

    // Permission: admin/mod OR chief whip (party leader is fallback if no chief whip assigned)
    const isAdminOrMod = hasAdminOrMod(req);
    if (!isAdminOrMod) {
      const charId = await getActiveCharacterId(req);
      if (!charId) return res.status(403).json({ error: "No active character" });
      const { rows: ptyRows } = await pool.query(
        "SELECT leader_character_id, chief_whip_character_id FROM parties WHERE slug = $1", [partySlug]
      );
      if (!ptyRows.length) return res.status(404).json({ error: "Party not found" });
      // Chief Whip takes precedence; Party Leader is the fallback only when no Chief Whip is assigned.
      const chiefWhipId = ptyRows[0].chief_whip_character_id;
      const leaderId    = ptyRows[0].leader_character_id;
      let allowed = [];
      if (chiefWhipId) allowed = [String(chiefWhipId)];
      else if (leaderId) allowed = [String(leaderId)];
      if (!allowed.includes(String(charId))) {
        return res.status(403).json({ error: "Only the party chief whip (or party leader if no whip is assigned) can set party instructions" });
      }
    }

    const charId = await getActiveCharacterId(req);
    const { rows: clk } = await pool.query("SELECT sim_current_month, sim_current_year FROM sim_clock WHERE id = 'main'");
    const sm = clk[0]?.sim_current_month ?? 8;
    const sy = clk[0]?.sim_current_year  ?? 1997;
    const simStr = `${sy}-${String(sm).padStart(2, "0")}`;

    const { rows } = await pool.query(
      `INSERT INTO division_party_instructions
         (division_id, party_slug, position, whip_level, note, set_by_character_id, set_by_user_id, set_at_sim)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
       ON CONFLICT (division_id, party_slug)
       DO UPDATE SET position = EXCLUDED.position, whip_level = EXCLUDED.whip_level,
                     note = EXCLUDED.note, set_by_character_id = EXCLUDED.set_by_character_id,
                     set_by_user_id = EXCLUDED.set_by_user_id, set_at_sim = EXCLUDED.set_at_sim,
                     updated_at = now()
       RETURNING *`,
      [req.params.divisionId, partySlug, position, Number(whipLevel), note || null, charId || null, req.session.userId, simStr]
    );
    res.json({ ok: true, instruction: rows[0] });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

