// ═══════════════════════════════════════════════════════════════════════════
// SIMULATION STATE
// GET   /api/sim        — authenticated: get current sim state
// POST  /api/sim/tick   — admin: advance simulation clock by one month
// POST  /api/sim/set    — admin: set simulation state directly
// ═══════════════════════════════════════════════════════════════════════════

const simReadLimit  = rateLimit({ windowMs: 60_000, max: 200, standardHeaders: true, legacyHeaders: false });
const simWriteLimit = rateLimit({ windowMs: 60_000, max: 30,  standardHeaders: true, legacyHeaders: false });

app.get("/api/sim", simReadLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const [stateResult, clockResult] = await Promise.all([
      pool.query("SELECT id, year, month, is_paused, last_tick_at FROM sim_state WHERE id = 'main'"),
      pool.query("SELECT rate FROM sim_clock WHERE id = 'main'"),
    ]);
    if (!stateResult.rows.length) return res.status(404).json({ error: "Sim state not found" });
    if (!clockResult.rows.length) {
      console.warn("[GET /api/sim] sim_clock row 'main' not found — rate defaulting to 1");
    }
    res.json({ sim: { ...stateResult.rows[0], rate: clockResult.rows[0]?.rate ?? 1 } });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

app.post("/api/sim/tick", simWriteLimit, async (req, res) => {
  try {
    if (!requireAdmin(req, res)) return;
    const { rows } = await pool.query(`
      UPDATE sim_state
         SET month        = CASE WHEN month = 12 THEN 1 ELSE month + 1 END,
             year         = CASE WHEN month = 12 THEN year + 1 ELSE year END,
             last_tick_at = NOW()
       WHERE id = 'main' AND is_paused = FALSE
       RETURNING id, year, month, is_paused, last_tick_at
    `);
    if (!rows.length) {
      // Either not found or paused
      const { rows: current } = await pool.query("SELECT is_paused FROM sim_state WHERE id = 'main'");
      if (current.length && current[0].is_paused) {
        return res.status(409).json({ error: "Simulation is paused" });
      }
      return res.status(404).json({ error: "Sim state not found" });
    }
    // Keep sim_clock in sync so both clock representations agree.
    await pool.query(
      `UPDATE sim_clock SET sim_current_month = $1, sim_current_year = $2, real_last_tick = NOW() WHERE id = 'main'`,
      [rows[0].month, rows[0].year]
    );
    await writeAuditLog(req.session.userId, "sim.tick", "sim_state", "main", null, rows[0]);

    // Automatic salary crediting — runs on every tick (catch-up for missed 2-month periods)
    fireRecompute("salary-crediting", "sim.tick", () => runSalaryCrediting(rows[0].month, rows[0].year));
    runShopUpkeep(rows[0].month, rows[0].year).catch((e) => console.error("[sim/tick] shop upkeep failed:", e.message));
    runMembershipIntake(rows[0].month, rows[0].year).catch((e) => console.error("[sim/tick] membership intake failed:", e.message));
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

app.post("/api/sim/set", simWriteLimit, async (req, res) => {
  try {
    if (!requireAdmin(req, res)) return;
    const { year, month, is_paused } = req.body || {};
    if (year != null && (typeof year !== "number" || year < 1900 || year > 2200)) {
      return res.status(400).json({ error: "year must be a number between 1900 and 2200" });
    }
    if (month != null && (typeof month !== "number" || month < 1 || month > 12)) {
      return res.status(400).json({ error: "month must be a number between 1 and 12" });
    }

    const { rows: before } = await pool.query("SELECT year, month, is_paused FROM sim_state WHERE id = 'main'");
    if (!before.length) return res.status(404).json({ error: "Sim state not found" });

    const fields = [];
    const params = [];
    if (year      != null) { params.push(year);      fields.push(`year = $${params.length}`); }
    if (month     != null) { params.push(month);     fields.push(`month = $${params.length}`); }
    if (is_paused != null) { params.push(is_paused); fields.push(`is_paused = $${params.length}`); }
    if (!fields.length) return res.status(400).json({ error: "Nothing to update" });

    params.push("main");
    const { rows } = await pool.query(
      `UPDATE sim_state SET ${fields.join(", ")} WHERE id = $${params.length}
       RETURNING id, year, month, is_paused, last_tick_at`,
      params
    );
    // Keep sim_clock in sync when year/month change.
    if (year != null || month != null) {
      await pool.query(
        `UPDATE sim_clock SET
           sim_current_month = $1,
           sim_current_year  = $2,
           real_last_tick    = NOW()
         WHERE id = 'main'`,
        [rows[0].month, rows[0].year]
      );
    }
    await writeAuditLog(req.session.userId, "sim.set", "sim_state", "main", before[0], rows[0]);
    res.json({ ok: true, sim: rows[0] });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// BILLS — add PATCH for stage transitions (triggers Discourse on 2nd Reading)
// PATCH /api/bills/:id   — admin/mod: update bill fields (stage triggers Discourse)
// ═══════════════════════════════════════════════════════════════════════════

app.patch("/api/bills/:id", crudWriteLimit, async (req, res) => {
  try {
    if (!requireAdminOrMod(req, res)) return;
    const { rows: before } = await pool.query("SELECT id, data FROM bills WHERE id = $1", [req.params.id]);
    if (!before.length) return res.status(404).json({ error: "Bill not found" });

    const updated = { ...before[0].data, ...req.body, id: req.params.id };
    const { rows } = await pool.query(
      "UPDATE bills SET data = $1::jsonb, updated_at = NOW() WHERE id = $2 RETURNING id, data, updated_at",
      [JSON.stringify(updated), req.params.id]
    );

    const newStage = updated.stage || updated.status;
    const oldStage = before[0].data?.stage || before[0].data?.status;

    // Auto-create Discourse topic when bill enters Second Reading (if not already linked)
    let topicUrl = updated.discourseTopicUrl || null;
    if (
      newStage === "second_reading" &&
      oldStage !== "second_reading" &&
      !updated.discourseTopicId
    ) {
      try {
        const { baseUrl, apiKey, apiUsername } = await loadDiscourseCredentials();
        const title = `[Bill] ${updated.title || req.params.id} — Second Reading Debate`;
        const raw   = updated.summary || updated.body || `Debate on **${updated.title || req.params.id}** at Second Reading.`;
        const { topicId, topicUrl: url } = await dcWithRetry(
          () => dcCreateTopic(baseUrl, apiKey, apiUsername, title, raw, 9),
          3, 500
        );
        topicUrl = url;
        await pool.query(
          `UPDATE bills SET data = data || $1::jsonb, discourse_topic_id = $3, discourse_topic_url = $4, updated_at = NOW() WHERE id = $2`,
          [JSON.stringify({ discourseTopicId: topicId, discourseTopicUrl: url }), req.params.id, String(topicId), url]
        );
        rows[0].data = { ...rows[0].data, discourseTopicId: topicId, discourseTopicUrl: url };
      } catch (discErr) {
        // Non-fatal: log and continue; topic can be synced manually
        console.error("[bills/patch] Discourse auto-topic failed:", discErr.message);
      }
    }

    await writeAuditLog(req.session.userId, "bill.patch", "bill", req.params.id, before[0].data, rows[0].data);
    res.json({ ok: true, bill: { ...rows[0].data, _updatedAt: rows[0].updated_at }, topicUrl });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// ADMIN: Discourse sync — re-sync bills missing Discourse topic link
// POST /api/admin/discourse-sync-bills — admin
// ═══════════════════════════════════════════════════════════════════════════

const discourseBillSyncLimit = rateLimit({ windowMs: 60_000, max: 5, standardHeaders: true, legacyHeaders: false });

app.post("/api/admin/discourse-sync-bills", discourseBillSyncLimit, async (req, res) => {
  try {
    if (!requireAdmin(req, res)) return;

    // Find bills at second_reading stage without a Discourse topic
    const { rows: bills } = await pool.query(
      `SELECT id, data FROM bills
        WHERE (data->>'stage' = 'second_reading' OR data->>'status' = 'second_reading')
          AND data->>'discourseTopicId' IS NULL`
    );

    if (!bills.length) return res.json({ ok: true, synced: 0, message: "No bills need syncing" });

    let baseUrl, apiKey, apiUsername;
    try {
      ({ baseUrl, apiKey, apiUsername } = await loadDiscourseCredentials());
    } catch (credErr) {
      return res.status(400).json({ ok: false, error: credErr.message });
    }

    const results = [];
    for (const bill of bills) {
      try {
        const title = `[Bill] ${bill.data.title || bill.id} — Second Reading Debate`;
        const raw   = bill.data.summary || bill.data.body || `Debate on **${bill.data.title || bill.id}** at Second Reading.`;
        const { topicId, topicUrl } = await dcWithRetry(
          () => dcCreateTopic(baseUrl, apiKey, apiUsername, title, raw, 9),
          3, 500
        );
        await pool.query(
          `UPDATE bills SET data = data || $1::jsonb, discourse_topic_id = $3, discourse_topic_url = $4, updated_at = NOW() WHERE id = $2`,
          [JSON.stringify({ discourseTopicId: topicId, discourseTopicUrl: topicUrl }), bill.id, String(topicId), topicUrl]
        );
        results.push({ id: bill.id, ok: true, topicId, topicUrl });
      } catch (err) {
        results.push({ id: bill.id, ok: false, error: err.message });
      }
    }

    const synced = results.filter((r) => r.ok).length;
    await writeAuditLog(req.session.userId, "admin.discourse-sync-bills", "bills", "*", null, { synced, results });
    res.json({ ok: true, synced, results });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

const discourseDebateSyncLimit = rateLimit({ windowMs: 60_000, max: 10, standardHeaders: true, legacyHeaders: false });

// Default Discourse category ID for bills debate topics (matches historical hard-coded value).
// Override via app_config key 'discourse_category_bills' or env var DISCOURSE_CATEGORY_BILLS.
const DEFAULT_BILLS_DISCOURSE_CATEGORY_ID = 9;

app.post("/api/admin/discourse-sync-debates", discourseDebateSyncLimit, async (req, res) => {
  try {
    if (!requireAdmin(req, res)) return;

    const kind = String(req.body?.kind || "").trim().toLowerCase();
    const ALLOWED = new Set(["bills", "motions", "statements", "regulations"]);
    if (!ALLOWED.has(kind)) {
      return res.status(400).json({ ok: false, error: "kind must be one of: bills, motions, statements, regulations" });
    }

    let baseUrl, apiKey, apiUsername;
    try {
      ({ baseUrl, apiKey, apiUsername } = await loadDiscourseCredentials());
    } catch (credErr) {
      return res.status(400).json({ ok: false, error: credErr.message });
    }

    // Load per-kind Discourse category IDs from app_config (keys: discourse_category_bills,
    // discourse_category_motions, discourse_category_statements, discourse_category_regulations).
    // Fall back to environment variables (DISCOURSE_CATEGORY_BILLS etc.) then to 9 for bills.
    // For other kinds, the category MUST be configured — if missing, return an actionable error.
    const { rows: catRows } = await pool.query(
      `SELECT key, value FROM app_config
        WHERE key IN (
          'discourse_category_bills',
          'discourse_category_motions',
          'discourse_category_statements',
          'discourse_category_regulations'
        )`
    );
    const catCfg = Object.fromEntries(catRows.map((r) => [r.key, r.value]));

    function resolveCategoryId(k) {
      const cfgVal = catCfg[`discourse_category_${k}`];
      if (cfgVal) return Number(cfgVal);
      const envVar = process.env[`DISCOURSE_CATEGORY_${k.toUpperCase()}`];
      if (envVar) return Number(envVar);
      return null;
    }

    const kindCategoryId = resolveCategoryId(kind) ?? (kind === "bills" ? DEFAULT_BILLS_DISCOURSE_CATEGORY_ID : null);
    if (!kindCategoryId) {
      return res.status(400).json({
        ok: false,
        error: `Discourse category ID not configured for kind "${kind}". ` +
               `Set app_config key "discourse_category_${kind}" or environment variable ` +
               `DISCOURSE_CATEGORY_${kind.toUpperCase()} to the numeric Discourse category ID.`,
      });
    }

    let rows = [];
    if (kind === "bills") {
      const out = await pool.query(
        `SELECT id, data FROM bills
          WHERE (data->>'stage' = 'second_reading' OR data->>'status' = 'second_reading')
            AND COALESCE(discourse_topic_id, data->>'discourseTopicId') IS NULL`
      );
      rows = out.rows;
    } else if (kind === "motions") {
      const out = await pool.query(
        `SELECT id, data FROM motions
          WHERE motion_type = 'house'
            AND COALESCE(discourse_topic_id, data->>'discourseTopicId') IS NULL
            AND COALESCE(data->>'status', 'open') NOT IN ('closed','archived')`
      );
      rows = out.rows;
    } else if (kind === "statements") {
      const out = await pool.query(
        `SELECT id, data FROM statements
          WHERE COALESCE(discourse_topic_id, data->>'discourseTopicId') IS NULL
            AND COALESCE(data->>'status', 'open') NOT IN ('closed','archived')`
      );
      rows = out.rows;
    } else {
      const out = await pool.query(
        `SELECT id, data FROM regulations
          WHERE COALESCE(discourse_topic_id, data->>'discourseTopicId') IS NULL
            AND COALESCE(data->>'status', 'open') NOT IN ('closed','archived')`
      );
      rows = out.rows;
    }

    const results = [];
    for (const row of rows) {
      try {
        let title;
        let raw;
        let tags;

        if (kind === "bills") {
          title = `[Bill ${row.id}] ${row.data.title || row.id} — Second Reading Debate`;
          raw = row.data.summary || row.data.body || `Debate on **${row.data.title || row.id}** at Second Reading.`;
          tags = ["bill", "second-reading"];
        } else if (kind === "motions") {
          title = `[Motion ${row.id}] ${row.data.title || "House Motion"} — Debate`;
          raw = row.data.text || `Debate opened for motion **${row.data.title || row.id}**.`;
          tags = ["motion", "house"];
        } else if (kind === "statements") {
          title = `[Statement ${row.id}] ${row.data.title || "Ministerial Statement"} — Debate`;
          raw = row.data.text || `Debate opened for statement **${row.data.title || row.id}**.`;
          tags = ["statement"];
        } else {
          title = `[Regulation ${row.id}] ${row.data.shortTitle || row.data.title || "Government Regulation"} — Debate`;
          raw = row.data.text || `Debate opened for regulation **${row.data.shortTitle || row.data.title || row.id}**.`;
          tags = ["regulation"];
        }

        const { topicId, topicUrl } = await dcWithRetry(
          () => dcCreateTopic(baseUrl, apiKey, apiUsername, title, raw, kindCategoryId, tags),
          3,
          500
        );

        await pool.query(
          `UPDATE ${kind}
              SET data = data || $1::jsonb,
                  discourse_topic_id = $3,
                  discourse_topic_url = $4,
                  updated_at = NOW()
            WHERE id = $2`,
          [JSON.stringify({ discourseTopicId: topicId, discourseTopicUrl: topicUrl }), row.id, String(topicId), topicUrl]
        );
        results.push({ id: row.id, ok: true, topicId, topicUrl });
      } catch (err) {
        results.push({ id: row.id, ok: false, error: err.message });
      }
    }

    const synced = results.filter((r) => r.ok).length;
    await writeAuditLog(req.session.userId, `admin.discourse-sync-${kind}`, kind, "*", null, { synced, results });
    res.json({ ok: true, kind, synced, results });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Server error" });
  }
});

// ═══════════════════════════════════════════════════════════════════════════
// ADMIN: wipe-content — safe sim reset (no user/registration deletion)
// POST /api/admin/wipe-content
//
// Wipes gameplay/content tables and resets the sim clock + state to the
// August 1997 baseline.  User accounts and pending registrations are
// NOT touched.  Requires a typed confirmation body: { confirm: "WIPE CONTENT" }
//
// ── demo.json safety ────────────────────────────────────────────────────────
// data/demo.json is a static read-only file on disk served directly to
// logged-out browsers.  This endpoint only issues SQL TRUNCATE statements
// against the live PostgreSQL database and never reads from, writes to, or
// deletes any filesystem files.  demo.json is therefore completely unaffected
// by any wipe operation.
// ════════════════════════════════════════════════════════════════════════════

const wipeContentLimit = rateLimit({ windowMs: 60_000, max: 5, standardHeaders: true, legacyHeaders: false });

app.post("/api/admin/wipe-content", wipeContentLimit, async (req, res) => {
  try {
    if (!isDevSeedAllowed()) return res.status(404).json({ error: "Not found" });
    if (!requireAdmin(req, res)) return;

    const { confirm: confirmText } = req.body || {};
    if (confirmText !== "WIPE CONTENT") {
      return res.status(400).json({
        ok: false,
        error: "Confirmation text mismatch. Type WIPE CONTENT exactly to proceed.",
      });
    }

    // Wipe all gameplay/content tables (expanded to include all content categories)
    // Note: questiontime_questions = legacy JSON-blob QT; qt_questions = new structured QT table
    await pool.query(`
      TRUNCATE
        bills, bill_amendments, bill_amendment_supporters, bill_stage_reports, bill_opposition_quota,
        motions,
        statements,
        regulations,
        questiontime_questions,
        qt_questions, qt_answers, qt_followups,
        press_items,
        polling_entries,
        elections, election_party_summary, election_constituency_changes, constituency_events,
        news_stories, newspaper_articles,
        divisions, division_votes, division_party_instructions, division_rebellion_log, division_rebel_requests,
        game_events,
        scandal_situations, scandals, scandal_player_choices, scandal_mod_decisions,
        red_lion_posts, online_posts, fundraising_items,
        privy_council_posts,
        cs_briefings, cs_cases,
        frontbench_reshuffles
      CASCADE
    `);

    // Vacate all office assignments (clear government and opposition to vacant)
    await pool.query(`TRUNCATE office_assignments, office_assignment_history CASCADE`);

    // Reset group_drafts (clear cabinet and shadow cabinet drafts)
    await pool.query(`UPDATE group_drafts SET drafts = '[]'::jsonb, updated_at = NOW()`);

    // Reset budget_data to 1997 baseline
    await seedBudgetBaseline(true);

    // Re-seed 1997 base election (idempotent)
    await seedElection1997();

    // Reset sim clock to August 1997
    await pool.query(`
      INSERT INTO sim_clock (id, sim_current_month, sim_current_year, rate)
      VALUES ('main', 8, 1997, 1)
      ON CONFLICT (id) DO UPDATE SET
        sim_current_month = 8,
        sim_current_year  = 1997,
        rate              = 1,
        real_last_tick    = NOW()
    `);

    // Reset sim_state to August 1997
    await pool.query(`
      INSERT INTO sim_state (id, year, month, is_paused)
      VALUES ('main', 1997, 8, true)
      ON CONFLICT (id) DO UPDATE SET
        year        = 1997,
        month       = 8,
        is_paused   = true,
        last_tick_at = NULL
    `);

    // Reset app_state_current — create a fresh empty snapshot and point to it
    const { rows: snapRows } = await pool.query(
      `INSERT INTO state_snapshots (label, data)
         VALUES ('Post-wipe baseline (August 1997)', '{}'::jsonb)
       RETURNING id`
    );
    const newSnapshotId = snapRows[0].id;
    await pool.query(
      `INSERT INTO app_state_current (id, snapshot_id)
         VALUES ('main', $1)
       ON CONFLICT (id) DO UPDATE SET snapshot_id = $1`,
      [newSnapshotId]
    );

    await writeAuditLog(req.session.userId, "admin.wipe-content", "all", "*", null, {
      headline: "Wipe Content: all IC simulation content cleared, sim reset to August 1997",
      simMonth: 8,
      simYear: 1997,
      // questiontime_questions = legacy JSON-blob QT table; qt_questions = new structured QT table
      tables: [
        "bills", "bill_amendments", "bill_amendment_supporters", "bill_stage_reports", "bill_opposition_quota",
        "motions", "statements", "regulations",
        "questiontime_questions", "qt_questions", "qt_answers", "qt_followups",
        "press_items", "polling_entries",
        "elections", "election_party_summary", "election_constituency_changes", "constituency_events",
        "news_stories", "newspaper_articles",
        "divisions", "division_votes", "division_party_instructions", "division_rebellion_log", "division_rebel_requests",
        "game_events", "scandal_situations", "scandals", "scandal_player_choices", "scandal_mod_decisions",
        "red_lion_posts", "online_posts", "fundraising_items",
        "privy_council_posts", "cs_briefings", "cs_cases", "frontbench_reshuffles",
        "office_assignments (vacated)", "group_drafts (reset)", "budget_data (reset to 1997)",
      ],
      simResetTo: "August 1997",
      newSnapshotId,
    });

    // Ensure baseline constituencies are present after reset (idempotent — skips if already seeded)
    await seedConstituencies1997();

    res.json({
      ok: true,
      message: "Content wiped and sim reset to August 1997. All offices vacated, drafts cleared, budget reset. User accounts and characters are intact.",
      wiped: [
        "bills", "bill_amendments", "motions", "statements", "regulations",
        "questiontime_questions", "qt_questions", "press_items", "polling_entries",
        "elections (re-seeded 1997 base)", "news_stories", "newspaper_articles",
        "divisions", "division_votes", "game_events", "scandals",
        "red_lion_posts", "online_posts", "fundraising_items",
        "privy_council_posts", "cs_briefings", "cs_cases",
        "office_assignments (vacated)", "group_drafts (reset)", "budget_data (reset)",
      ],
      simResetTo: "August 1997",
    });
  } catch (e) {
    console.error("[wipe-content]", e);
    res.status(500).json({ ok: false, error: "Server error during wipe" });
  }
});

