// GET /api/me/faction — active character's live faction membership
app.get("/api/me/faction", charAppReadLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const characterId = await getActiveCharacterId(req);
    if (!characterId) return res.json({ faction: null });

    const { rows: charRows } = await pool.query(
      `SELECT id, party, is_active FROM characters WHERE id = $1 AND is_active = TRUE LIMIT 1`,
      [characterId]
    );
    if (!charRows.length) return res.json({ faction: null });
    const character = charRows[0];

    const membership = await ensureCharacterFactionMembership(pool, character);
    if (!membership) return res.json({ faction: null });

    const { rows } = await pool.query(
      `SELECT f.id, f.slug, f.name, f.party_slug, f.colour
         FROM character_faction_membership cfm
         JOIN party_factions f ON f.id = cfm.faction_id
        WHERE cfm.character_id = $1
        LIMIT 1`,
      [characterId]
    );
    if (!rows.length) return res.json({ faction: null });
    res.json({ faction: rows[0] });
  } catch (e) {
    console.error("[GET /api/me/faction]", e);
    res.status(500).json({ error: "Server error" });
  }
});

// POST /api/me/faction/switch — switch active character faction (once per sim year)
app.post("/api/me/faction/switch", verifyCsrfToken, charAppWriteLimit, async (req, res) => {
  const client = await pool.connect();
  try {
    if (!requireAuth(req, res)) return;
    const characterId = await getActiveCharacterId(req);
    if (!characterId) return res.status(400).json({ error: "No active character selected" });

    const newFactionId = String(req.body?.faction_id || "").trim();
    if (!newFactionId) return res.status(400).json({ error: "faction_id is required" });

    await client.query("BEGIN");

    const { rows: charRows } = await client.query(
      `SELECT id, name, party, is_active FROM characters WHERE id = $1 AND is_active = TRUE LIMIT 1`,
      [characterId]
    );
    if (!charRows.length) {
      await client.query("ROLLBACK");
      return res.status(404).json({ error: "Active character not found" });
    }
    const character = charRows[0];

    if (!FACTION_PLAYABLE_PARTIES.includes(String(character.party || ""))) {
      await client.query("ROLLBACK");
      return res.status(400).json({ error: "Faction membership is not available for this party" });
    }

    await getOrCreateUnalignedFaction(character.party, client);

    const { rows: newFactionRows } = await client.query(
      `SELECT id, slug, name, party_slug, active FROM party_factions WHERE id = $1 LIMIT 1`,
      [newFactionId]
    );
    if (!newFactionRows.length || !newFactionRows[0].active) {
      await client.query("ROLLBACK");
      return res.status(400).json({ error: "Selected faction is invalid or inactive" });
    }
    const newFaction = newFactionRows[0];
    if (String(newFaction.party_slug) !== String(character.party)) {
      await client.query("ROLLBACK");
      return res.status(400).json({ error: "Selected faction must belong to your party" });
    }

    if (await characterHasBlockedFactionRole(character.id, character.party)) {
      await client.query("ROLLBACK");
      return res.status(403).json({ error: "Party leaders/chairmen/whips cannot switch faction while in office" });
    }

    const simYear = await getCurrentSimYear();

    const current = await ensureCharacterFactionMembership(client, character);
    if (!current) {
      await client.query("ROLLBACK");
      return res.status(400).json({ error: "Faction membership is not available for this party" });
    }

    if (String(current.faction_id) === String(newFaction.id)) {
      await client.query("ROLLBACK");
      return res.status(400).json({ error: "You are already in that faction" });
    }
    if (current.last_switch_sim_year != null && Number(current.last_switch_sim_year) === simYear) {
      await client.query("ROLLBACK");
      return res.status(400).json({ error: "Faction can only be switched once per sim year" });
    }

    await client.query(
      `UPDATE character_faction_membership
          SET faction_id = $2, last_switch_sim_year = $3, updated_at = NOW()
        WHERE character_id = $1`,
      [character.id, newFaction.id, simYear]
    );

    await client.query("COMMIT");

    await writeAuditLog(req.session.userId, "faction.switch", "character", character.id, null, null, {
      target: character.name || character.id,
      partySlug: character.party,
      fromFactionId: current.faction_id,
      fromFactionSlug: current.from_slug,
      toFactionId: newFaction.id,
      toFactionSlug: newFaction.slug,
      simYear,
    });

    fireRecompute("character-political-state", "faction.switch", () => recomputeCharacterPoliticalState(character.id), character.id);

    return res.json({ ok: true, faction: { id: newFaction.id, slug: newFaction.slug, name: newFaction.name, party_slug: newFaction.party_slug } });
  } catch (e) {
    try { await client.query("ROLLBACK"); } catch {}
    console.error("[POST /api/me/faction/switch]", e);
    res.status(500).json({ error: "Server error" });
  } finally {
    client.release();
  }
});

// ── Party Faction API ─────────────────────────────────────────────────────────

// FACTION_PLAYABLE_PARTIES imported from political-state-service.js

/** Normalise a faction slug: lowercase, hyphens instead of spaces. */
function normaliseFactionSlug(s) {
  return String(s)
    .toLowerCase()
    .trim()
    .replace(/\s+/g, "-")
    .replace(/[^a-z0-9-]/g, "")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
}

/**
 * Return the total number of constituency MPs held by a party.
 * Note: the constituencies table stores the full party name (e.g. "Conservative")
 * in the party column, which matches the party_slug values used throughout the
 * system (slug === name for playable parties).
 * Uses the canonical constituencies table as the source of truth.
 */
async function getOrCreateUnalignedFaction(partySlug, db = pool) {
  if (!FACTION_PLAYABLE_PARTIES.includes(partySlug)) return null;
  const { rows: existing } = await db.query(
    `SELECT id, slug FROM party_factions
      WHERE party_slug = $1 AND slug = 'unaligned'
      LIMIT 1`,
    [partySlug]
  );
  if (existing.length) {
    if (existing[0].slug === 'unaligned') {
      await db.query(`UPDATE party_factions SET active = TRUE, leadership_alignment = 'neutral', updated_at = NOW() WHERE id = $1`, [existing[0].id]);
    }
    return existing[0].id;
  }
  const { rows: created } = await db.query(
    `INSERT INTO party_factions
       (party_slug, slug, name, description, colour, ideology_tags, leadership_alignment, display_order, active)
     VALUES ($1, 'unaligned', 'Unaligned', 'Members not aligned to any organised parliamentary faction.', '#777777', '[]'::jsonb, 'neutral', 9999, TRUE)
     RETURNING id`,
    [partySlug]
  );
  await db.query(
    `INSERT INTO party_faction_allocations (faction_id, mp_count, influence_bonus, notes, updated_by)
     VALUES ($1, 0, 0, 'System default faction', 'system')
     ON CONFLICT (faction_id) DO NOTHING`,
    [created[0].id]
  );
  return created[0].id;
}

async function ensureUnalignedFactionsForPlayableParties() {
  for (const partySlug of FACTION_PLAYABLE_PARTIES) {
    await getOrCreateUnalignedFaction(partySlug);
  }
}

const OTHER_OFFICIALS_ARENA_TYPES = new Set(["body", "locals"]);

function emptyPlayablePartyTotals() {
  return { Labour: 0, Conservative: 0, "Liberal Democrat": 0 };
}

function buildPlayablePartyTotalsFromRows(rows, fieldName) {
  const totals = emptyPlayablePartyTotals();
  const safeRows = Array.isArray(rows) ? rows : [];
  for (const row of safeRows) {
    const party = String(row?.party || "");
    if (!FACTION_PLAYABLE_PARTIES.includes(party)) continue;
    const parsed = Number(row?.[fieldName]);
    totals[party] = Number.isFinite(parsed) ? parsed : 0;
  }
  return totals;
}

async function getOtherOfficialsTotalsForPlayableParties() {
  const [bodyRowsResult, localsResult] = await Promise.all([
    pool.query("SELECT id, data FROM bodies_data ORDER BY sort_order ASC, id ASC"),
    pool.query("SELECT value FROM app_config WHERE key = 'locals_data'"),
  ]);

  const totalsByArena = {};
  const contributingArenas = [];

  for (const row of bodyRowsResult.rows) {
    const body = row?.data || {};
    const bodyId = String(row?.id || body?.id || "").trim();
    if (!bodyId) continue;

    const mayors = Array.isArray(body?.mayors) ? body.mayors : [];
    const includeBody = Boolean(
      body?.visible || (bodyId === "directly-elected-mayors" && mayors.length > 0)
    );
    if (!includeBody) continue;

    let totals = emptyPlayablePartyTotals();
    if (bodyId === "directly-elected-mayors") {
      // for DEM each mayor is exactly one official
      totals = emptyPlayablePartyTotals();
      for (const mayor of mayors) {
        const party = String(mayor?.party || "");
        if (!FACTION_PLAYABLE_PARTIES.includes(party)) continue;
        totals[party] += 1;
      }
    } else {
      totals = buildPlayablePartyTotalsFromRows(body?.partyBreakdown, "seats");
    }

    const arenaKey = `body:${bodyId}`;
    totalsByArena[arenaKey] = totals;
    contributingArenas.push({
      arenaType: "body",
      arenaId: bodyId,
      label: body?.title || body?.name || bodyId,
      visible: true,
    });
  }

  const localsData = localsResult.rows[0]?.value ? JSON.parse(localsResult.rows[0].value) : {};
  const countries = Array.isArray(localsData?.countries) ? localsData.countries : [];
  const localsByCountry = new Map(countries.map((row) => [String(row?.country || "").trim(), row]));
  const fallbackCountries = ["England", "Scotland", "Wales", "Northern Ireland"];
  for (const countryName of fallbackCountries) {
    const countryRow = localsByCountry.get(countryName) || { country: countryName, partyBreakdown: [] };
    const country = String(countryRow?.country || "").trim();
    if (!country) continue;
    const totals = buildPlayablePartyTotalsFromRows(countryRow?.partyBreakdown, "councillors");
    const arenaKey = `locals:${country}`;
    totalsByArena[arenaKey] = totals;
    contributingArenas.push({
      arenaType: "locals",
      arenaId: country,
      label: country,
      visible: true,
    });
  }

  return { totalsByArena, contributingArenas };
}

async function getCurrentSimYear() {
  const { rows } = await pool.query("SELECT sim_current_year FROM sim_clock WHERE id = 'main'");
  return Number(rows[0]?.sim_current_year ?? 1997);
}

async function normalisePartySlugFromCharacterParty(partyName, db = pool) {
  const name = String(partyName || "").trim();
  if (!name) return "";
  const { rows } = await db.query(
    `SELECT slug, name
       FROM parties
      WHERE lower(slug) = lower($1) OR lower(name) = lower($1)
      ORDER BY CASE WHEN lower(slug) = lower($1) THEN 0 ELSE 1 END
      LIMIT 1`,
    [name]
  );
  return rows[0]?.slug || name;
}

async function characterHasBlockedFactionRole(characterId, partyName) {
  const partySlug = await normalisePartySlugFromCharacterParty(partyName);
  const { rows } = await pool.query(
    `SELECT 1
       FROM parties
      WHERE (slug = $2 OR name = $3) AND (
        leader_character_id = $1 OR
        chairman_character_id = $1 OR
        chief_whip_character_id = $1 OR
        deputy_whip_character_id = $1 OR
        whip_character_id = $1
      )
      LIMIT 1`,
    [characterId, partySlug, partyName]
  );
  return rows.length > 0;
}

async function ensureCharacterFactionMembership(db, character) {
  if (!character?.id || !FACTION_PLAYABLE_PARTIES.includes(String(character.party || ""))) return null;

  const { rows: currentRows } = await db.query(
    `SELECT cfm.character_id, cfm.faction_id, cfm.last_switch_sim_year, f.slug AS from_slug
       FROM character_faction_membership cfm
       JOIN party_factions f ON f.id = cfm.faction_id
      WHERE cfm.character_id = $1
      FOR UPDATE`,
    [character.id]
  );
  if (currentRows.length) return currentRows[0];

  const unalignedFactionId = await getOrCreateUnalignedFaction(character.party, db);
  if (!unalignedFactionId) return null;

  await db.query(
    `INSERT INTO character_faction_membership (character_id, faction_id, joined_at, updated_at)
     VALUES ($1, $2, NOW(), NOW())
     ON CONFLICT (character_id) DO NOTHING`,
    [character.id, unalignedFactionId]
  );

  const { rows: createdRows } = await db.query(
    `SELECT cfm.character_id, cfm.faction_id, cfm.last_switch_sim_year, f.slug AS from_slug
       FROM character_faction_membership cfm
       JOIN party_factions f ON f.id = cfm.faction_id
      WHERE cfm.character_id = $1
      FOR UPDATE`,
    [character.id]
  );
  return createdRows[0] || null;
}

async function getPartyConstituencyMPs(partyName) {
  const { rows } = await pool.query(
    `SELECT COUNT(*) AS total FROM constituencies WHERE party = $1`,
    [partyName]
  );
  return Number(rows[0]?.total || 0);
}

// GET /api/admin/parties/:slug/factions
app.get("/api/admin/parties/:slug/factions", crudReadLimit, async (req, res) => {
  try {
    if (!requireAdminOrMod(req, res)) return;
    const { slug } = req.params;
    if (!FACTION_PLAYABLE_PARTIES.includes(slug)) {
      return res.status(400).json({ error: `Factions only supported for: ${FACTION_PLAYABLE_PARTIES.join(", ")}` });
    }
    await getOrCreateUnalignedFaction(slug);
    const [factionsResult, totalMPs] = await Promise.all([
      pool.query(
        `SELECT f.*, a.mp_count, a.influence_bonus, a.notes, a.updated_by, a.updated_at AS allocation_updated_at
           FROM party_factions f
           LEFT JOIN party_faction_allocations a ON a.faction_id = f.id
          WHERE f.party_slug = $1
          ORDER BY f.display_order ASC, f.name ASC`,
        [slug]
      ),
      getPartyConstituencyMPs(slug),
    ]);
    const factions = factionsResult.rows.map((r) => ({
      id:                      r.id,
      partySlug:               r.party_slug,
      slug:                    r.slug,
      name:                    r.name,
      description:             r.description,
      colour:                  r.colour,
      ideologyTags:            Array.isArray(r.ideology_tags) ? r.ideology_tags : [],
      leadershipAlignment:     r.leadership_alignment,
      rebellionBias:           Number(r.rebellion_bias),
      mediaSensitivity:        Number(r.media_sensitivity),
      constituencySensitivity: Number(r.constituency_sensitivity),
      displayOrder:            Number(r.display_order),
      active:                  Boolean(r.active),
      createdAt:               r.created_at,
      updatedAt:               r.updated_at,
      mpCount:                 Number(r.mp_count ?? 0),
      influenceBonus:          Number(r.influence_bonus ?? 0),
      notes:                   r.notes ?? "",
      updatedBy:               r.updated_by ?? "",
      allocationUpdatedAt:     r.allocation_updated_at ?? null,
    }));
    const allocatedMPs = factions.filter((f) => f.active).reduce((sum, f) => sum + f.mpCount, 0);
    // allocatedMPs intentionally only counts active factions; inactive faction allocations
    // are preserved for history but do not count against the party's available MP total.
    res.json({ factions, totalMPs, allocatedMPs, remainingMPs: totalMPs - allocatedMPs });
  } catch (e) {
    console.error("[GET /api/admin/parties/:slug/factions]", e);
    res.status(500).json({ error: "Server error" });
  }
});

