// GET /api/admin/other-officials/faction-allocations?arena_type=...&arena_id=...&party_slug=...
app.get("/api/admin/other-officials/faction-allocations", crudReadLimit, async (req, res) => {
  try {
    if (!requireAdminOrMod(req, res)) return;
    const arenaType = String(req.query?.arena_type || "").trim();
    const arenaId = String(req.query?.arena_id || "").trim();
    const partySlug = String(req.query?.party_slug || "").trim();

    if (!OTHER_OFFICIALS_ARENA_TYPES.has(arenaType)) {
      return res.status(400).json({ error: "arena_type must be body or locals" });
    }
    if (!arenaId) return res.status(400).json({ error: "arena_id is required" });
    if (!FACTION_PLAYABLE_PARTIES.includes(partySlug)) {
      return res.status(400).json({ error: `party_slug must be one of: ${FACTION_PLAYABLE_PARTIES.join(", ")}` });
    }

    await getOrCreateUnalignedFaction(partySlug);
    const { totalsByArena } = await getOtherOfficialsTotalsForPlayableParties();
    const partyTotalInArena = Number(totalsByArena[`${arenaType}:${arenaId}`]?.[partySlug] ?? 0);

    const [factionsResult, existingResult] = await Promise.all([
      pool.query(
        `SELECT id, slug, name, party_slug, active, display_order
           FROM party_factions
          WHERE party_slug = $1 AND active = TRUE
          ORDER BY display_order ASC, name ASC`,
        [partySlug]
      ),
      pool.query(
        `SELECT faction_id, official_count, updated_by, updated_at
           FROM other_officials_faction_allocations
          WHERE arena_type = $1 AND arena_id = $2 AND party_slug = $3`,
        [arenaType, arenaId, partySlug]
      ),
    ]);

    const existingByFaction = new Map(existingResult.rows.map((r) => [r.faction_id, r]));
    const factions = factionsResult.rows.map((f) => {
      const existing = existingByFaction.get(f.id);
      return {
        id: f.id,
        slug: f.slug,
        name: f.name,
        partySlug: f.party_slug,
        active: Boolean(f.active),
        officialCount: Number(existing?.official_count ?? 0),
        updatedBy: String(existing?.updated_by || ""),
        updatedAt: existing?.updated_at || null,
      };
    });
    const allocatedOfficials = factions.reduce((sum, f) => sum + Number(f.officialCount || 0), 0);

    res.json({
      ok: true,
      arenaType,
      arenaId,
      partySlug,
      partyTotalInArena,
      allocatedOfficials,
      unallocatedOfficials: Math.max(0, partyTotalInArena - allocatedOfficials),
      factions,
    });
  } catch (e) {
    console.error("[GET /api/admin/other-officials/faction-allocations]", e);
    res.status(500).json({ error: "Server error" });
  }
});

// PUT /api/admin/other-officials/faction-allocations
app.put("/api/admin/other-officials/faction-allocations", verifyCsrfToken, crudWriteLimit, async (req, res) => {
  const client = await pool.connect();
  try {
    if (!requireAdminOrMod(req, res)) return;
    const arenaType = String(req.body?.arena_type || "").trim();
    const arenaId = String(req.body?.arena_id || "").trim();
    const partySlug = String(req.body?.party_slug || "").trim();
    const allocations = Array.isArray(req.body?.allocations) ? req.body.allocations : null;

    if (!OTHER_OFFICIALS_ARENA_TYPES.has(arenaType)) {
      return res.status(400).json({ error: "arena_type must be body or locals" });
    }
    if (!arenaId) return res.status(400).json({ error: "arena_id is required" });
    if (!FACTION_PLAYABLE_PARTIES.includes(partySlug)) {
      return res.status(400).json({ error: `party_slug must be one of: ${FACTION_PLAYABLE_PARTIES.join(", ")}` });
    }
    if (!allocations) {
      return res.status(400).json({ error: "allocations must be an array" });
    }

    await getOrCreateUnalignedFaction(partySlug, client);

    const { totalsByArena } = await getOtherOfficialsTotalsForPlayableParties();
    const partyTotalInArena = Number(totalsByArena[`${arenaType}:${arenaId}`]?.[partySlug] ?? 0);

    const factionIds = allocations.map((a) => String(a?.faction_id || "").trim()).filter(Boolean);
    const uniqueFactionIds = Array.from(new Set(factionIds));
    if (uniqueFactionIds.length !== allocations.length) {
      return res.status(400).json({ error: "allocations contains duplicate faction_id values" });
    }

    const parsedAllocations = allocations.map((a) => ({
      factionId: String(a?.faction_id || "").trim(),
      officialCount: Number(a?.official_count),
    }));
    for (const item of parsedAllocations) {
      if (!item.factionId) return res.status(400).json({ error: "Each allocation requires faction_id" });
      if (!Number.isInteger(item.officialCount) || item.officialCount < 0) {
        return res.status(400).json({ error: "Each official_count must be an integer >= 0" });
      }
    }
    const allocationSum = parsedAllocations.reduce((sum, a) => sum + a.officialCount, 0);
    if (allocationSum > partyTotalInArena) {
      return res.status(400).json({ error: `Allocation sum (${allocationSum}) exceeds party total in arena (${partyTotalInArena})` });
    }

    const { rows: factionRows } = uniqueFactionIds.length
      ? await client.query(
          `SELECT id, party_slug, active FROM party_factions WHERE id = ANY($1::uuid[])`,
          [uniqueFactionIds]
        )
      : { rows: [] };
    if (factionRows.length !== uniqueFactionIds.length) {
      return res.status(400).json({ error: "One or more faction_id values do not exist" });
    }
    for (const row of factionRows) {
      if (String(row.party_slug) !== partySlug) {
        return res.status(400).json({ error: "All faction_id values must belong to the selected party" });
      }
      if (!row.active) {
        return res.status(400).json({ error: "All faction_id values must be active" });
      }
    }

    await client.query("BEGIN");
    await client.query(
      `DELETE FROM other_officials_faction_allocations
        WHERE arena_type = $1 AND arena_id = $2 AND party_slug = $3`,
      [arenaType, arenaId, partySlug]
    );
    for (const item of parsedAllocations) {
      await client.query(
        `INSERT INTO other_officials_faction_allocations
           (arena_type, arena_id, party_slug, faction_id, official_count, updated_by, updated_at)
         VALUES ($1, $2, $3, $4, $5, $6, NOW())
         ON CONFLICT (arena_type, arena_id, party_slug, faction_id)
         DO UPDATE SET official_count = EXCLUDED.official_count,
                       updated_by = EXCLUDED.updated_by,
                       updated_at = NOW()`,
        [arenaType, arenaId, partySlug, item.factionId, item.officialCount, req.session.userId || ""]
      );
    }
    await client.query("COMMIT");

    res.json({
      ok: true,
      arenaType,
      arenaId,
      partySlug,
      partyTotalInArena,
      allocatedOfficials: allocationSum,
      unallocatedOfficials: Math.max(0, partyTotalInArena - allocationSum),
    });
  } catch (e) {
    try { await client.query("ROLLBACK"); } catch {}
    console.error("[PUT /api/admin/other-officials/faction-allocations]", e);
    res.status(500).json({ error: "Server error" });
  } finally {
    client.release();
  }
});

// POST /api/admin/parties/:slug/factions
app.post("/api/admin/parties/:slug/factions", verifyCsrfToken, crudWriteLimit, async (req, res) => {
  try {
    if (!requireAdminOrMod(req, res)) return;
    const { slug } = req.params;
    if (!FACTION_PLAYABLE_PARTIES.includes(slug)) {
      return res.status(400).json({ error: `Factions only supported for: ${FACTION_PLAYABLE_PARTIES.join(", ")}` });
    }
    const {
      name, slug: factionSlug, description = "", colour = "#888888",
      ideologyTags = [], leadershipAlignment = "neutral",
      rebellionBias = 0, mediaSensitivity = 0, constituencySensitivity = 0,
      displayOrder = 0, active = true,
    } = req.body || {};
    const canonicalFactionSlug = normaliseFactionSlug(factionSlug);
    if (!name || !canonicalFactionSlug) {
      return res.status(400).json({ error: "name and slug are required" });
    }
    const { rows } = await pool.query(
      `INSERT INTO party_factions
         (party_slug, slug, name, description, colour, ideology_tags, leadership_alignment,
          rebellion_bias, media_sensitivity, constituency_sensitivity, display_order, active)
       VALUES ($1,$2,$3,$4,$5,$6::jsonb,$7,$8,$9,$10,$11,$12)
       RETURNING id`,
      [
        slug, canonicalFactionSlug,
        String(name), String(description), String(colour),
        JSON.stringify(Array.isArray(ideologyTags) ? ideologyTags : []),
        String(leadershipAlignment),
        Number(rebellionBias) || 0, Number(mediaSensitivity) || 0,
        Number(constituencySensitivity) || 0, Number(displayOrder) || 0,
        active !== false,
      ]
    );
    const newId = rows[0].id;
    // Create a default allocation row
    await pool.query(
      `INSERT INTO party_faction_allocations (faction_id, mp_count, updated_by) VALUES ($1, 0, $2)`,
      [newId, req.session.userId || ""]
    );
    res.status(201).json({ ok: true, id: newId });
  } catch (e) {
    if (e.code === "23505") {
      return res.status(409).json({ error: "A faction with that slug already exists for this party." });
    }
    console.error("[POST /api/admin/parties/:slug/factions]", e);
    res.status(500).json({ error: "Server error" });
  }
});

// PATCH /api/admin/factions/:id
app.patch("/api/admin/factions/:id", verifyCsrfToken, crudWriteLimit, async (req, res) => {
  try {
    if (!requireAdminOrMod(req, res)) return;
    const { id } = req.params;
    // Verify faction exists
    const { rows: existing } = await pool.query("SELECT id, party_slug FROM party_factions WHERE id = $1", [id]);
    if (!existing.length) return res.status(404).json({ error: "Faction not found" });
    if (!FACTION_PLAYABLE_PARTIES.includes(existing[0].party_slug)) {
      return res.status(400).json({ error: "Cannot edit factions for this party" });
    }
    const sets = [];
    const vals = [];
    const body = req.body || {};
    if (body.name !== undefined)                  { sets.push(`name = $${vals.push(String(body.name))}`); }
    if (body.slug !== undefined) {
      const canonicalFactionSlug = normaliseFactionSlug(body.slug);
      if (!canonicalFactionSlug) {
        return res.status(400).json({ error: "slug must contain at least one alphanumeric character" });
      }
      sets.push(`slug = $${vals.push(canonicalFactionSlug)}`);
    }
    if (body.description !== undefined)           { sets.push(`description = $${vals.push(String(body.description))}`); }
    if (body.colour !== undefined)                { sets.push(`colour = $${vals.push(String(body.colour))}`); }
    if (body.ideologyTags !== undefined)          { sets.push(`ideology_tags = $${vals.push(JSON.stringify(Array.isArray(body.ideologyTags) ? body.ideologyTags : []))}::jsonb`); }
    if (body.leadershipAlignment !== undefined)   { sets.push(`leadership_alignment = $${vals.push(String(body.leadershipAlignment))}`); }
    if (body.rebellionBias !== undefined)         { sets.push(`rebellion_bias = $${vals.push(Number(body.rebellionBias) || 0)}`); }
    if (body.mediaSensitivity !== undefined)      { sets.push(`media_sensitivity = $${vals.push(Number(body.mediaSensitivity) || 0)}`); }
    if (body.constituencySensitivity !== undefined) { sets.push(`constituency_sensitivity = $${vals.push(Number(body.constituencySensitivity) || 0)}`); }
    if (body.displayOrder !== undefined)          { sets.push(`display_order = $${vals.push(Number(body.displayOrder) || 0)}`); }
    if (body.active !== undefined)                { sets.push(`active = $${vals.push(body.active !== false && body.active !== "false")}`); }
    if (!sets.length) return res.status(400).json({ error: "No fields to update" });
    sets.push(`updated_at = NOW()`);
    vals.push(id);
    await pool.query(`UPDATE party_factions SET ${sets.join(", ")} WHERE id = $${vals.length}`, vals);
    res.json({ ok: true });

    // Non-blocking: if leadership_alignment or rebellion_bias changed, faction political state may be stale
    const factionStateFieldsChanged = body.leadershipAlignment !== undefined || body.rebellionBias !== undefined;
    if (factionStateFieldsChanged) {
      fireRecompute("faction-political-state", "faction.metadata.update", () => computeFactionPoliticalState(id), id);
    }
  } catch (e) {
    if (e.code === "23505") {
      return res.status(409).json({ error: "A faction with that slug already exists for this party." });
    }
    console.error("[PATCH /api/admin/factions/:id]", e);
    res.status(500).json({ error: "Server error" });
  }
});

// PATCH /api/admin/factions/:id/allocation
app.patch("/api/admin/factions/:id/allocation", verifyCsrfToken, crudWriteLimit, async (req, res) => {
  try {
    if (!requireAdminOrMod(req, res)) return;
    const { id } = req.params;
    const { rows: existing } = await pool.query(
      "SELECT f.id, f.party_slug, f.active FROM party_factions f WHERE f.id = $1", [id]
    );
    if (!existing.length) return res.status(404).json({ error: "Faction not found" });
    const faction = existing[0];
    if (!FACTION_PLAYABLE_PARTIES.includes(faction.party_slug)) {
      return res.status(400).json({ error: "Cannot edit factions for this party" });
    }
    const { mpCount, influenceBonus, notes } = req.body || {};
    const newMpCount = Number(mpCount);
    if (!Number.isInteger(newMpCount) || newMpCount < 0) {
      return res.status(400).json({ error: "mp_count must be a non-negative integer" });
    }
    // Validate: sum of active faction mp_counts for this party must not exceed total constituency MPs
    const [totalMPs, sumResult] = await Promise.all([
      getPartyConstituencyMPs(faction.party_slug),
      pool.query(
        `SELECT COALESCE(SUM(a.mp_count), 0) AS total
           FROM party_factions f
           JOIN party_faction_allocations a ON a.faction_id = f.id
          WHERE f.party_slug = $1
            AND f.active = TRUE
            AND f.id <> $2`,
        [faction.party_slug, id]
      ),
    ]);
    const otherActiveTotal = Number(sumResult.rows[0].total);
    const proposedTotal = faction.active ? otherActiveTotal + newMpCount : otherActiveTotal;
    if (proposedTotal > totalMPs) {
      return res.status(400).json({
        error: `Allocation would exceed party's constituency MPs. Total: ${totalMPs}, already allocated: ${otherActiveTotal}, proposed: ${newMpCount}.`,
        totalMPs,
        allocatedMPs: otherActiveTotal,
        remainingMPs: totalMPs - otherActiveTotal,
      });
    }
    await pool.query(
      `INSERT INTO party_faction_allocations (faction_id, mp_count, influence_bonus, notes, updated_by, updated_at)
       VALUES ($1, $2, $3, $4, $5, NOW())
       ON CONFLICT (faction_id) DO UPDATE
         SET mp_count = EXCLUDED.mp_count,
             influence_bonus = EXCLUDED.influence_bonus,
             notes = EXCLUDED.notes,
             updated_by = EXCLUDED.updated_by,
             updated_at = NOW()`,
      [
        id, newMpCount,
        Number(influenceBonus) || 0,
        String(notes ?? ""),
        req.session.userId || "",
      ]
    );
    res.json({ ok: true, totalMPs, allocatedMPs: proposedTotal, remainingMPs: totalMPs - proposedTotal });

    // Non-blocking: recompute faction political state now that allocation has changed
    fireRecompute("faction-political-state", "faction.allocation.update", () => computeFactionPoliticalState(id), id);
  } catch (e) {
    console.error("[PATCH /api/admin/factions/:id/allocation]", e);
    res.status(500).json({ error: "Server error" });
  }
});

// GET /api/parties/:slug/factions  (player-facing, read-only, no hidden modifiers)
app.get("/api/parties/:slug/factions", crudReadLimit, async (req, res) => {
  try {
    if (!requireAuth(req, res)) return;
    const { slug } = req.params;
    await getOrCreateUnalignedFaction(slug);
    const [fRows, totalsRows] = await Promise.all([
      pool.query(
        `SELECT f.id, f.name, f.slug, f.description, f.colour, f.ideology_tags,
                f.display_order, f.active,
                COALESCE(a.mp_count, 0) AS mp_count,
                COALESCE(a.influence_bonus, 0) AS influence_bonus,
                COALESCE(ps.internal_power, 0) AS internal_power,
                COALESCE(ps.momentum, 'stable') AS momentum,
                COALESCE(ps.cohesion, 0) AS cohesion,
                COALESCE(ps.leadership_pressure, 0) AS leadership_pressure,
                f.leadership_alignment AS leadership_alignment,
                COALESCE(mc.member_character_count_active, 0) AS member_character_count_active,
                COALESCE(mn.member_npc_count_active, 0) AS member_npc_count_active
           FROM party_factions f
           LEFT JOIN party_faction_allocations a ON a.faction_id = f.id
           LEFT JOIN faction_political_state ps ON ps.faction_id = f.id
           LEFT JOIN (
             SELECT cfm.faction_id, COUNT(*)::INT AS member_character_count_active
               FROM character_faction_membership cfm
               JOIN characters c ON c.id = cfm.character_id
              WHERE c.is_active = TRUE AND c.is_npc = FALSE
              GROUP BY cfm.faction_id
           ) mc ON mc.faction_id = f.id
           LEFT JOIN (
             SELECT cfm.faction_id, COUNT(*)::INT AS member_npc_count_active
               FROM character_faction_membership cfm
               JOIN characters c ON c.id = cfm.character_id
              WHERE c.is_active = TRUE AND c.is_npc = TRUE
              GROUP BY cfm.faction_id
           ) mn ON mn.faction_id = f.id
          WHERE f.party_slug = $1 AND f.active = TRUE
          ORDER BY f.display_order ASC, f.name ASC`,
        [slug]
      ),
      pool.query(
        `SELECT
            (SELECT COUNT(*)::INT FROM constituencies WHERE party = $1) AS party_seat_total,
            COALESCE((
              SELECT SUM(a.mp_count)::INT
                FROM party_factions f
                JOIN party_faction_allocations a ON a.faction_id = f.id
               WHERE f.party_slug = $1 AND f.active = TRUE
            ), 0) AS allocated_mps`,
        [slug]
      ),
    ]);

    const factions = fRows.rows.map((r) => ({
      id: r.id,
      name: r.name,
      slug: r.slug,
      description: r.description,
      colour: r.colour,
      ideologyTags: Array.isArray(r.ideology_tags) ? r.ideology_tags : [],
      displayOrder: Number(r.display_order),
      active: Boolean(r.active),
      mpCount: Number(r.mp_count),
      influenceBonus: Number(r.influence_bonus),
      internalPower: Number(r.internal_power),
      momentum: r.momentum,
      cohesion: Number(r.cohesion),
      leadershipAlignment: String(r.leadership_alignment || "neutral"),
      leadershipPressure: Number(r.leadership_pressure),
      memberCharacterCountActive: Number(r.member_character_count_active),
      memberNpcCountActive: Number(r.member_npc_count_active),
    }));
    const partySeatTotal = Number(totalsRows.rows[0]?.party_seat_total ?? 0);
    const allocatedMPs = Number(totalsRows.rows[0]?.allocated_mps ?? 0);
    res.json({ factions, partySeatTotal, allocatedMPs, remainingMPs: partySeatTotal - allocatedMPs });
  } catch (e) {
    console.error("[GET /api/parties/:slug/factions]", e);
    res.status(500).json({ error: "Server error" });
  }
});

